insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحَدَكُمْ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ أَتَى الْمَسْجِدَ، لَا يَنْهَزُهُ إِلَّا الصَّلَاةَ، لَمْ يَخْطُ خَطْوَةً إِلَّا رَفَعَهُ اللهُ عَزَّ وَجَلَّ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً، حَتَّى يَدْخُلَ الْمَسْجِدَ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ വുളു ചെയ്യുകയും, അത് പരിപൂർണ്ണമാക്കുകയും ചെയ്തശേഷം പള്ളിയിൽ വന്നു, നിസ്കാരം മാത്രമാണവനെ പള്ളിയിലെത്തിച്ചത്. എങ്കിൽ ഓരോ ചവിട്ടടിയിലും അല്ലാഹു അവന്റെ സ്ഥാനം ഉയർത്തുകയും അവന്റെ ദോഷം പൊറുത്തു കൊടുക്കുകയും ചെയ്യുന്നതാണ്. അങ്ങനെ അവൻ പള്ളിയിൽ പ്രവേശിക്കുന്നതു വരെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَمْرِو بْنِ عَبْسَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْعَبْدَ إِذَا تَوَضَّأَ فَغَسَلَ يَدَيْهِ خَرَّتْ خَطَايَاهُ مِنْ يَدَيْهِ، فَإِذَا غَسَلَ وَجْهَهُ خَرَّتْ خَطَايَاهُ مِنْ وَجْهِهِ، فَإِذَا غَسَلَ ذِرَاعَيْهِ وَمَسَحَ بِرَأْسِهِ خَرَّتْ خَطَايَاهُ مِنْ ذِرَاعَيْهِ وَرَأْسِهِ، فَإِذَا غَسَلَ رِجْلَيْهِ خَرَّتْ خَطَايَاهُ مِنْ رِجْلَيْهِ". (جه)', 'അംറുബ്നു അബസ(റ): നബി(സ) പറഞ്ഞു: "ഒരടിമ വുദൂ ചെയ്യുന്നു, അവൻ കൈകൾ കഴുകുമ്പോൾ അതുകൊണ്ട് ചെയ്ത ദോഷങ്ങൾ കൊഴിഞ്ഞു പോകുന്നു, മുഖം കഴുകുമ്പോൾ മുഖത്തു നിന്ന് ദോഷങ്ങൾ വീണുപോവുന്നു. കണങ്കൈകൾ കഴുകുമ്പോഴും തല തടവുമ്പോഴും അവയിലെ ദോഷങ്ങൾ കൊഴിഞ്ഞു പോകുന്നു. കാലുകൾ കഴുകുമ്പോൾ അതിലെ ദോഷങ്ങളും കൊഴിഞ്ഞുപോകുന്നു." (ജ)', 'عَمْرِو بْنِ عَبْسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللهِ، كَيْفَ تَعْرِفُ مَنْ لَمْ تَرَ مِنْ أُمَّتِكَ؟ قَالَ: "غُرٌّ مُحَجَّلُونَ بُلْقٌ، مِنْ آثَارِ الْوُضُوءِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, അങ്ങയുടെ സമുദായത്തിൽ നിന്നും ഒരിക്കലും താങ്കൾ കണ്ടിട്ടില്ലാത്തവരെ അങ്ങ് എങ്ങനെ തിരിച്ചറിയും? നബി(സ) പറഞ്ഞു: "വുദൂവിന്റെ അടയാളത്താൽ അവരുടെ മുഖവും മുൻകൈകളും കാലുകളും പ്രകാശിക്കുന്നവരായിരിക്കും." (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ حُمْرَانَ – مَوْلَى عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ – قَالَ: رَأَيْتُ عُثْمَانَ بْنَ عَفَّانَ قَاعِدًا فِي الْمَقَاعِدِ، فَدَعَا بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَقْعَدِي هَذَا تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا، ثُمَّ قَالَ: "مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَلَا تَغْتَرُّوا". (ق,جه)', 'ഹുംറാൻ(റ) (ഉസ്മാനി(റ)ന്റെ അടിമ): ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) ഇരിപ്പിടത്തിൽ ഇരുന്നുകൊണ്ട് വുദൂ ചെയ്യാൻ വെള്ളം ആവശ്യപ്പെടുന്നത് ഞാൻ കണ്ടു. അദ്ദേഹം വുളു ചെയ്തു. ശേഷം പറഞ്ഞു: ഞാനിരുന്ന ഇതേ സ്ഥലത്തിരുന്ന് ഞാൻ ചെയ്തതുപോലെ നബി(സ) വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. ശേഷം പറഞ്ഞു: "ഞാൻ വുദൂ ചെയ്തതുപോലെ ആരെങ്കിലും വുദൂ ചെയ്താൽ അവന്റെ മുൻകഴിഞ്ഞ ദോഷങ്ങൾ പൊറുക്കപ്പെടും." നബി(സ) പറഞ്ഞു: "പക്ഷെ, നിങ്ങൾ വഞ്ചിതരായിപ്പോകരുത്." (ബു,മു,ജ)', 'حُمْرَانَ – مَوْلَى عُثْمَانَ بْنِ عَفَّانَ', 'ഹുംറാൻ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 155, 155, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَقْبَلُ اللهُ صَلَاةً بِغَيْرِ طُهُورٍ، وَلَا صَدَقَةً مِنْ غُلُولٍ". [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ശുദ്ധിയില്ലാതെയുള്ള നിസ്കാരവും വഞ്ചിച്ചു കിട്ടിയതിൽ നിന്നുള്ള ദാനവും അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِسْبَاغُ الْوُضُوءِ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ مِلْءُ الْمِيزَانِ، وَالتَّسْبِيحُ وَالتَّكْبِيرُ مِلْءُ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالزَّكَاةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو: فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا". (جه)', 'അബൂമാലികിൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "പരിപൂർണ്ണമായ വുദൂ ഈമാനിന്റെ ഭാഗമാണ്. അൽഹംദുലില്ലാഹ് എന്നത് മീസാൻ (ത്രാസ്) നിറക്കും, തസ്ബീഹും തക്ബീറും ആകാശ ഭൂമികൾ നിറക്കും, നിസ്കാരം പ്രകാശമാണ്, സകാത്ത് തെളിവും, ക്ഷമ ശോഭയുമാണ്, ഖുർആൻ (അനുകൂലമായോ പ്രതികൂലമായോ) നിന്റെ സാക്ഷിയാണ്. ജനങ്ങളെല്ലാം പ്രഭാതത്തിൽ യാത്രപുറപ്പെടുന്നു, എന്നിട്ട് തന്റെ നഫ്സിനെ വിൽക്കുകയും, അതിനെ രക്ഷപ്പെടുത്തുകയോ, ആപത്തിലാക്കുകയോ ചെയ്യുകയും ചെയ്യുന്നു" (ജ)', 'أَبِي مَالِكٍ الْأَشْعَرِيِّ', 'അബൂമാലികിൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْتَقِيمُوا وَلَنْ تُحْصُوا، وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمُ الصَّلَاةَ، وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ". [في سنده إنقطاع] (جه)', 'സൗബാൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നേരെയാവുക, നിങ്ങൾ ക്ലിപ്തമാക്കരുത്. അറിയുക; നിങ്ങളുടെ കർമ്മങ്ങളിൽ വെച്ചേറ്റവും നല്ലകർമ്മം നിസ്കാരമാണ്. വിശ്വാസിയല്ലാതെ വുദൂ പതിവാക്കുകയില്ല." (ഇതിന്റെ പരമ്പര മുറിഞ്ഞിട്ടുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده إنقطاع', null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ لِكُلِّ صَلَاةٍ، وَكُنَّا نَحْنُ نُصَلِّي الصَّلَوَاتِ كُلَّهَا بِوُضُوءٍ وَاحِدٍ. (خ,د,ت,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഓരോ നിസ്കാരത്തിനും പ്രത്യേകം വുദൂ ചെയ്യാറുണ്ടായിരുന്നു. ഞങ്ങൾ ഒറ്റ വുദൂ കൊണ്ട് എല്ലാ നിസ്കാരങ്ങളും നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. (ബു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 156, 156, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ لِكُلِّ صَلَاةٍ، فَلَمَّا كَانَ يَوْمُ الْفَتْحِ صَلَّى الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ، فَقَالَ لَهُ عُمَرُ: فَعَلْتَ شَيْئًا لَمْ تَكُنْ تَفْعَلُهُ؟ قَالَ: "عَمْدًا فَعَلْتُهُ يَا عُمَرُ". (م,د,ت,ن,جه)', 'ബുറൈദ(റ): നബി(സ) എല്ലാ നിസ്കാരങ്ങൾക്കും വുദൂ ചെയ്യാറുണ്ടായിരുന്നു. മക്കാ വിജയ ദിനമായപ്പോൾ ഒരു വുദൂ കൊണ്ട് എല്ലാ നിസ്കാരങ്ങളും നിർവ്വഹിച്ചു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അങ്ങ് ചെയ്യാത്ത ഒരു കാര്യമാണല്ലോ ഇപ്പോൾ ചെയ്തിരിക്കുന്നത്. നബി(സ) പറഞ്ഞു: "ഉമറേ, ഞാനത് മനഃപൂർവ്വമാണ് ചെയ്തത്." (മു,ദ,തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ الْفَضْلِ بْنِ مُبَشِّرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ جَابِرَ بْنَ عَبْدِ اللهِ-رضي الله عنه- يُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ، فَقُلْتُ: مَا هَذَا؟ فَقَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ هَذَا، فَأَنَا أَصْنَعُ كَمَا صَنَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ഫള്ലുബ്നു മുബശ്ശിർ(റ): ജാബിർ(റ) എല്ലാ നിസ്കാരങ്ങളും ഒരു വുദൂ കൊണ്ട് നിർവ്വഹിക്കുന്നതായി കണ്ടപ്പോൾ ഞാൻ ചോദിച്ചു: ഇതെന്താണ്? അദ്ദേഹം പറഞ്ഞു: നബി(സ ) ഇപ്രകാരം ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. അവിടുന്ന് കാണിച്ചു തന്നതുപോലെ ഞാൻ ചെയ്യും. (ജ)', 'الْفَضْلِ بْنِ مُبَشِّرٍ', 'ഫള്ലുബ്നു മുബശ്ശിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِإِنَاءٍ صَغِيرٍ، فَتَوَضَّأَ. قِيلَ: أَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ لِكُلِّ صَلَاةٍ؟ قَالَ: نَعَمْ، قَالَ: فَأَنْتُمْ؟ قَالَ: كُنَّا نُصَلِّي الصَّلَوَاتِ مَا لَمْ نُحْدِثْ، قَالَ: وَقَدْ كُنَّا نُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ. (ن)', 'അനസ്(റ): നബി(സ)ക്ക് ഒരു ചെറിയ വെള്ളപ്പാത്രം കൊണ്ടുവരപ്പെട്ടപ്പോൾ അതിൽ നിന്നു വുദൂ ചെയ്തു. അനസി(റ)നോട് ചോദിക്കപ്പെട്ടു: നബി(സ) എല്ലാ നിസ്കാരങ്ങൾക്കും വുദൂ ചെയ്യാറുണ്ടായിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതെ. അപ്പോൾ ചോദിക്കപ്പെട്ടു: നിങ്ങളോ? അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ അശുദ്ധിക്കാരല്ലാത്തപ്പോൾ നിസ്കരിക്കാറുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ വുദൂവോടു കൂടെയായിരുന്നു നിസ്കരിച്ചിരുന്നത്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ، فَقَالُوا: أَلَا نَأْتِيكَ بِوَضُوءٍ؟ فَقَالَ: "إِنَّمَا أُمِرْتُ بِالْوُضُوءِ إِذَا قُمْتُ إِلَى الصَّلَاةِ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) വിസർജ്ജനാവശ്യം കഴിഞ്ഞു പുറത്തുവന്നു ശേഷം ഭക്ഷണം കൊണ്ടുവരപ്പെട്ടു. ആളുകൾ ചോദിച്ചു: ഞങ്ങളങ്ങേക്ക് വുദൂഇനുള്ള വെള്ളം കൊണ്ടുവരട്ടെയോ? നബി(സ) പറഞ്ഞു: "ഞാൻ നിസ്കാരത്തിന്ന് നിന്നാൽ മാത്രമെ വുദൂ ചെയ്യാൻ കൽപിക്കപ്പെട്ടിട്ടുള്ളൂ." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 157, 157, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ النَّزَّالِ بْنِ سَبْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عَلِيًّا رَضِيَ اللهُ عَنْهُ صَلَّى الظُّهْرَ، ثُمَّ قَعَدَ لِحَوَائِجِ النَّاسِ، فَلَمَّا حَضَرَتِ الْعَصْرُ أُتِيَ بِتَوْرٍ مِنْ مَاءٍ، فَأَخَذَ مِنْهُ كَفًّا فَمَسَحَ بِهِ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ وَرِجْلَيْهِ، ثُمَّ أَخَذَ فَضْلَهُ فَشَرِبَ قَائِمًا، وَقَالَ: إِنَّ نَاسًا يَكْرَهُونَ هَذَا، وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ، وَهَذَا وُضُوءُ مَنْ لَمْ يُحْدِثْ. (ن)', 'നസ്സാലുബ്നു സബ്റ(റ): അലി(റ) ളുഹ്ർ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. പിന്നെയദ്ദേഹം ജനങ്ങളുടെ ആവശ്യങ്ങൾക്കായി ഇരുന്നു. അസ്ർ നിസ്കാര സമയമായപ്പോൾ ഒരു വെള്ളപ്പാത്രം കൊണ്ടുവരപ്പെട്ടു. അതിൽ നിന്നൊരു കവിളെടുത്ത് മുഖവും മുഴംകൈകളും രണ്ട് പാദങ്ങളും തടവി. പിന്നെ അതിന്റെ ബാക്കിയെടുത്ത് കുടിച്ചു. എന്നിട്ടു പറഞ്ഞു: നിശ്ചയം ജനങ്ങളിതു വെറുക്കുന്നു, എന്നാൽ നബി(സ) ഇപ്രകാരം ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. ഇതാണ് ചെറിയ അശുദ്ധിയില്ലാത്തവന്റെ വുദൂ. (ന)', 'النَّزَّالِ بْنِ سَبْرَةَ', 'നസ്സാലുബ്നു സബ്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 157, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِاللَّيْلِ رَكْعَتَيْنِ رَكْعَتَيْنِ، ثُمَّ يَنْصَرِفُ فَيَسْتَاكُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രാത്രിയിൽ ഈരണ്ട് റക്അത്തുകളായി നിസ്കരിക്കാറുണ്ടായിരുന്നു. ഓരോന്നും കഴിഞ്ഞശേഷം പല്ലുതേക്കും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ أَفْوَاهَكُمْ طُرُقٌ لِلْقُرْآنِ، فَطَيِّبُوهَا بِالسِّوَاكِ. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): അദ്ദേഹം പറഞ്ഞു: നിങ്ങളുടെ വായകൾ ഖുർആനിന്റെ മാർഗ്ഗങ്ങളാകുന്നു. മിസ്വാക്ക് കൊണ്ട് നിങ്ങളത് വൃത്തിയാക്കുക. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ رضي الله عنها: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا دَخَلَ بَيْتَهُ بَدَأَ بِالسِّوَاكِ. (م)', 'ആഇശ(റ): നബി(സ) തന്റെ വീട്ടിൽ പ്രവേശിച്ചാൽ ആദ്യം മിസ്വാക്ക് ചെയ്യാറുണ്ടായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْفِطْرَةُ خَمْسٌ، أَوْ خَمْسٌ مِنَ الْفِطْرَةِ: الْخِتَانُ، وَالِاسْتِحْدَادُ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبِطِ، وَقَصُّ الشَّارِبِ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഫിത്റത് (ചര്യകൾ) അഞ്ചെണ്ണമാണ്; -അല്ലെങ്കിൽ അഞ്ച് കാര്യങ്ങൾ ചര്യകളിൽ പെട്ടതാണ്- ചേലാകർമ്മം ചെയ്യൽ, ഗുഹ്യരോമം നീക്കൽ, നഖം മുറിക്കൽ, കക്ഷരോമം നീക്കൽ, മീശ വെട്ടൽ." (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مِنَ الْفِطْرَةِ: الْمَضْمَضَةُ، وَالِاسْتِنْشَاقُ، وَالسِّوَاكُ، وَقَصُّ الشَّارِبِ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبِطِ، وَالِاسْتِحْدَادُ، وَغَسْلُ الْبَرَاجِمِ، وَالِانْتِضَاحُ، وَالِاخْتِتَانُ". (د,جه)', 'അമ്മാറുബ്നു യാസിർ(റ): നബി(സ) പറഞ്ഞു: "വായിൽ വെള്ളം കൊപ്ലിക്കൽ, മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റൽ, ദന്ത ശുദ്ധീകരണം, മീശവെട്ടൽ, നഖം മുറിക്കൽ, കക്ഷരോമം നീക്കൽ, ഗുഹ്യരോമം നീക്കൽ, മൃഗങ്ങൾ താമസിക്കുന്ന ആല കഴുകൽ, ശൗച്യത്തിന് ഗുഹ്യഭാഗങ്ങളിൽ വെള്ളം കുടയൽ, ചേലാകർമ്മം ചെയ്യൽ എന്നിവ ഫിത്റത്തിൽ പെട്ടതാണ്" (ദ,ജ)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 158, 158, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سِتْرُ مَا بَيْنَ الْجِنِّ وَعَوْرَاتِ بَنِي آدَمَ - إِذَا دَخَلَ الْكَنِيفَ - أَنْ يَقُولَ: بِسْمِ اللهِ". (ت,جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "വിസർജ്ജന സ്ഥലത്ത് പ്രവേശിച്ചാൽ ആദം സന്തതികളുടെ മറക്കപ്പെടേണ്ടവയും ജിന്നുകൾക്കുമിടയിലുള്ള മറ ''ബിസ്മില്ലാഹി'' എന്നു പറയലാണ്. (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 158, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مِنَ الْخَلَاءِ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي". [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) വിസർജ്ജന സ്ഥലത്തുനിന്ന് പുറത്തു വരുമ്പോൾ പറയാറുണ്ടായിരുന്നു: "എന്നിൽ നിന്ന് ദോഷങ്ങൾ നീക്കി സുഖപ്പെടുത്തിയ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും." ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, '[?]', '', null, null, null, null, '{}'::text[], '{}'::text[], '?', null, 159, 159, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ نَاسًا يَقُولُونَ إِذَا قَعَدْتَ عَلَى حَاجَتِكَ فَلَا تَسْتَقْبِلِ الْقِبْلَةَ وَلَا بَيْتَ الْمَقْدِسِ. لَقَدِ ارْتَقَيْتُ يَوْمًا عَلَى ظَهْرِ بَيْتٍ لَنَا فَرَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى لَبِنَتَيْنِ مُسْتَقْبِلًا بَيْتَ الْمَقْدِسِ لِحَاجَتِهِ. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ) പറയുന്നു: മലമൂത്ര വിസർജ്ജനം നിർവ്വഹിക്കുകയാണെങ്കിൽ കഅ്ബക്കോ ബൈത്തുൽ മുഖദ്ദസിനോ അഭിമുഖമായി അത് നിർവ്വഹിക്കരുതെന്ന് ചില ആളുകൾ പറയുന്നു. (എന്നാൽ) ഒരു ദിവസം ഞാൻ ഞങ്ങളുടെ വീടിന്റെ മുകളിൽ കയറിയപ്പോൾ ബൈത്തുൽ മുഖദ്ദസിനു നേരെ തിരിഞ്ഞ് രണ്ട് ഇഷ്ടികകളിന്മേൽ ഇരുന്നുകൊണ്ട് പ്രവാചകൻ(സ) മലമൂത്രവിസർജ്ജനം നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട് (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ نَهَى عَنْ أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ. (م,ن,جه)', 'ജാബിർ(റ): കെട്ടി നിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിക്കുന്നത് നബി(സ) വിരോധിച്ചിരിക്കുന്നു. (മു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْغَيْضَةَ فَقَضَى حَاجَتَهُ، فَأَتَاهُ جَرِيرٌ بِإِدَاوَةٍ مِنْ مَاءٍ فَاسْتَنْجَى مِنْهَا، وَمَسَحَ يَدَهُ بِالتُّرَابِ. (جه)', 'ജരീർ(റ): ഞാൻ നബി(സ)യോടൊപ്പമായിരിക്കെ നബി(സ) ധാരാളം മരങ്ങളുള്ള ഒരു സ്ഥലത്തുചെന്ന് അവിടെ മലമൂത്ര വിസർജ്ജനം ചെയ്തു. പിന്നെ പറഞ്ഞു: "ജരീർ! വെള്ളം കൊണ്ടുവരൂ." ഞാൻ വെള്ളം കൊണ്ടുവന്നു. നബി(സ) ശുചീകരിക്കുകയും തന്റെ കൈ മണ്ണു കൊണ്ട് തടവുകയും ചെയ്തു. (ജ)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 159, 159, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا أَنَا لَكُمْ مِثْلُ الْوَالِدِ لِوَلَدِهِ، أُعَلِّمُكُمْ إِذَا أَتَيْتُمُ الْغَائِطَ فَلَا تَسْتَقْبِلُوا الْقِبْلَةَ وَلَا تَسْتَدْبِرُوهَا". وَأَمَرَ بِثَلَاثَةِ أَحْجَارٍ، وَنَهَى عَنِ الرَّوْثِ وَالرِّمَّةِ، وَنَهَى أَنْ يَسْتَطِيبَ الرَّجُلُ بِيَمِينِهِ. (د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് ഒരു പിതാവിനെപ്പോലെയാണ്, നിങ്ങളിലാരെങ്കിലും മലമൂത്ര വിസർജ്ജനത്തിനൊരുങ്ങിയാൽ ഖിബ്ലക്കു മുന്നിട്ടോ പിന്നിട്ടോ ഇരിക്കരുതെന്നും വലംകൈ കൊണ്ട് ശൗച്യം ചെയ്യരുതെന്നും ഞാൻ നിങ്ങളെ പഠിപ്പിക്കുന്നു." മൂന്ന് കല്ലുകൾ കൊണ്ട് ശൗച്യം ചെയ്യാൻ നബി(സ) കൽപിക്കാറുണ്ടായിരുന്നു. ദുർബലമായ വസ്തു കൊണ്ടും കാഷ്ഠം കൊണ്ടും ശൗച്യം ചെയ്യുന്നത് നബി(സ) വിലക്കിയിട്ടുമുണ്ട്. (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ أَحْمِلُ أَنَا وَغُلَامٌ مَعِي نَحْوِي إِدَاوَةً مِنْ مَاءٍ، فَيَسْتَنْجِي بِالْمَاءِ. (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) മലമൂത്ര വിസർജ്ജനത്തിനൊരുങ്ങിയാൽ കുട്ടിയായ ഞാനും ഒരു പാത്രത്തിൽ വെള്ളം ചുമക്കുകയും നബി(സ) അതു കൊണ്ട് ശൗച്യം ചെയ്യുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ". (ن)', 'ആഇശ(റ): നബി(സ) പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, തണുത്ത വെള്ളം കൊണ്ടും, മഞ്ഞുവെള്ളം കൊണ്ടും എന്റെ ദോഷങ്ങൾ കഴുകിക്കളയേണമേ, വെള്ള വസ്ത്രം അഴുക്കിൽ നിന്നും ശുദ്ധീകരിക്കും പോലെ എന്റെ ഹൃദയത്തെ ദോഷങ്ങളിൽ നിന്നും ശുദ്ധീകരിക്കേണമേ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى مَيِّتٍ، فَسَمِعْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ: "اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَأَوْسِعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ". (ن)', 'ഔഫുബ്നു മാലിക്(റ): നബി(സ) ഒരു മയ്യിത്തിന് വേണ്ടി നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, ഇദ്ദേഹത്തിന് നീ പൊറുത്തു കൊടക്കേണമേ, കരുണ ചെയ്യേണമേ, മാപ്പു നൽകേണമേ, സുഖം നൽകേണമേ, ഇദ്ദേഹത്തിന്റെ താമസസ്ഥലം നീ നന്നാക്കേണമേ, പ്രവേശന സ്ഥലം വിശാലമാക്കേണമേ, വെള്ളം കൊണ്ടും തണുത്ത മഞ്ഞുവെള്ളം കൊണ്ടും കഴുകി ശുദ്ധീകരിക്കേണമേ, വെള്ളവസ്ത്രം അഴുക്കിൽ നിന്നും ശുദ്ധീകരിക്കും പോലെ അദ്ദേഹത്തെ ദോഷങ്ങളിൽ നിന്നും സംശുദ്ധമാക്കേണമേ." (ന)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 160, 160, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَتَنَفَّسَ فِي الْإِنَاءِ، وَأَنْ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ، وَأَنْ يَسْتَطِيبَ بِيَمِينِهِ. (م,ن)', 'അബൂഖതാദ(റ): പാത്രത്തിൽ ഊതുന്നതും വലതുകൈ കൊണ്ട് ലിംഗം സ്പർശിക്കുന്നതും ശുദ്ധിയാക്കുന്നതും നബി(സ) വിലക്കിയിരിക്കുന്നു. (മു,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ الْمُشْرِكُونَ: إِنَّا لَنَرَى صَاحِبَكُمْ يُعَلِّمُكُمُ الْخِرَاءَةَ؟ قَالَ: أَجَلْ، نَهَانَا أَنْ يَسْتَنْجِيَ أَحَدُنَا بِيَمِينِهِ وَيَسْتَقْبِلَ الْقِبْلَةَ، وَقَالَ: "لَا يَسْتَنْجِي أَحَدُكُمْ بِدُونِ ثَلَاثَةِ أَحْجَارٍ". (ن)', 'സൽമാൻ(റ): ബഹുദൈവ വിശ്വാസികൾ പറഞ്ഞു: നിങ്ങളുടെ കൂട്ടുകാരൻ (നബി) നിങ്ങളെ മലമൂത്ര വിസർജ്ജനം ചെയ്യുന്നതിനെപ്പറ്റിപോലും പഠിപ്പിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: അതെ, ഞങ്ങൾ വലതുകൈ കൊണ്ട് ശൗച്യം ചെയ്യുന്നതും ഖിബ്ലക്കു മുന്നിടുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരും മൂന്നു കല്ലില്ലാതെ ശൗച്യം ചെയ്യരുത്." (ന)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى الْخَلَاءَ فَقَضَى الْحَاجَةَ، ثُمَّ قَالَ: "يَا جَرِيرُ، هَاتِ طَهُورًا". فَأَتَيْتُهُ بِالْمَاءِ، فَاسْتَنْجَى بِالْمَاءِ، وَقَالَ بِيَدِهِ فَدَلَكَ بِهَا الْأَرْضَ. (ن)', 'ജരീർ(റ): ഞാൻ നബി(സ)യോടൊപ്പമായിരിക്കെ അവിടുന്ന് മലമൂത്ര വിസർജ്ജനം ചെയ്തു. ശേഷം പറഞ്ഞു: "ജരീർ! വെള്ളം കൊണ്ടുവരൂ." ഞാൻ വെള്ളം കൊണ്ടുവന്നു. നബി(സ) ശുചീകരിക്കുകയും തന്റെ കൈ മണ്ണിലുരക്കുകയും ചെയ്തു. (ന)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَاءِ وَمَا يَنُوبُهُ مِنَ الدَّوَابِّ وَالسِّبَاعِ؟ فَقَالَ: "إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلِ الْخَبَثَ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മൃഗങ്ങളോ വന്യമൃഗങ്ങളോ തലയിടുന്ന വെള്ളത്തെക്കുറിച്ച് നബി(സ) ചോദിക്കപ്പെട്ടപ്പോൾ അവടുന്ന് പറഞ്ഞു: "വെള്ളം രണ്ട് ഖുല്ലതുണ്ടെങ്കിൽ അത് അശുദ്ധമാവില്ല." (ന)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَامَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ، فَتَنَاوَلَهُ النَّاسُ، فَقَالَ لَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعُوهُ، وَأَهْرِيقُوا عَلَى بَوْلِهِ دَلْوًا مِنْ مَاءٍ، فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ". (ن)', 'അബൂഹുറൈറ(റ): ഒരു അഅ്റാബി എഴുന്നേറ്റ് നിന്ന് പള്ളിയിൽ മൂത്രമൊഴിച്ചു, ജനങ്ങൾ അദ്ദേഹത്തെ പിടിച്ചു. നബി(സ) അവരോട് പറഞ്ഞു: അയാളെ വിട്ടേക്കുക, മൂത്രത്തിൽ ഒരു ബക്കറ്റ് വെള്ളമൊഴിക്കുക. നിശ്ചയം, നിങ്ങൾ അയക്കപ്പെട്ടത് എളുപ്പമുണ്ടാക്കുന്ന ആളുകളായിട്ടാണ്, നിങ്ങളൊരിക്കലും പ്രയാസപ്പെടുത്തുന്നുവരായി അയക്കപ്പെട്ടിട്ടില്ല. (ന)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ بِالْمُدِّ، وَيَغْتَسِلُ بِالصَّاعِ، إِلَى خَمْسَةِ أَمْدَادٍ. (م)', 'അനസ്(റ): നബി(സ) ഒരു മുദ്ദ് വെള്ളം കൊണ്ട് വുദൂ ചെയ്യാറുണ്ടായിരുന്നു. ഒരു സ്വാഅ് മുതൽ അഞ്ച് സ്വാഅ് വരെ വെള്ളം കൊണ്ട് കുളിക്കാറുമുണ്ടായിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 161, 161, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ هَمَّامٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَالَ جَرِيرٌ، ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ: تَفْعَلُ هَذَا؟ فَقَالَ: نَعَمْ، رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَالَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ، قَالَ الْأَعْمَشُ: قَالَ إِبْرَاهِيمُ: كَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ، لِأَنَّ إِسْلَامَ جَرِيرٍ كَانَ بَعْدَ نُزُولِ الْمَائِدَةِ. (م)', 'ഹമ്മാം(റ): ജരീർ മൂത്രമൊഴിച്ചു, പിന്നെ വുദൂ ചെയ്യുകയും ഖുഫ്ഫക്കു മീതെ തടവുകയും ചെയ്തു. അപ്പോൾ ചോദിക്കപ്പെട്ടു: നീ ഇങ്ങനെ ചെയ്യുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) മൂത്രമൊഴിക്കുകയും വുദൂ ചെയ്യുകയും ഖുഫ്ഫക്കു മുകളിൽ തടവുകയും ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. അഅ്മശ് പറഞ്ഞു: ഇബ്രാഹീം പറയുന്നു: ഈ ഹദീസ് അവരെ അത്ഭുതപ്പെടുത്തുന്നതായിരുന്നു. കാരണം ജരീറിന്റെ ഇസ്ലാമാശ്ലേഷണം സൂറത്തു മാഇദ ഇറങ്ങിയതിനു ശേഷമായിരുന്നു. (മു)', 'هَمَّامٍ', 'ഹമ്മാം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ بِمَكُّوكٍ، وَيَغْتَسِلُ بِخَمْسِ مَكَاكِيَّ. (ن)', 'അനസ്(റ): നബി(സ) ഒരു മുദ്ദ് വെള്ളം കൊണ്ട് വുദൂ ചെയ്യുകയും, അഞ്ച് മുദ്ദ് വെള്ളം കൊണ്ട് കുളിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أُمِّ عُمَارَةَ بِنْتُ كَعْبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ فَأُتِيَ بِمَاءٍ فِي إِنَاءٍ قَدْرِ ثُلُثَيِ الْمُدِّ. قَالَ شُعْبَةُ: فَأَحْفَظُ أَنَّهُ غَسَلَ ذِرَاعَيْهِ وَجَعَلَ يَدْلُكُهُمَا، وَيَمْسَحُ أُذُنَيْهِ بَاطِنَهُمَا، وَلَا أَحْفَظُ: أَنَّهُ مَسَحَ ظَاهِرَهُمَا. (ن)', 'ഉമ്മുഉമാറ(റ): നബി(സ) വുദൂ ചെയ്തു. അപ്പോൾ അവിടുത്തേക്ക് ഒരു മുദ്ദിന്റെ മൂന്നിൽ രണ്ടുഭാഗം വെള്ളം കൊണ്ടുവന്നു. ശുഅ്ബ(റ) പറയുന്നു: നബി(സ) മുഴംകൈകൾ തേച്ചു കഴുകിയതായും ചെവികളുടെ അകം തടവിയതായും ഞാൻ വ്യക്തമായി ഞാൻ ഓർക്കുന്നു. പുറം തടവിയതായി ഞാൻ മനസ്സിലാക്കിയിട്ടില്ല. (ന)', 'أُمِّ عُمَارَةَ بِنْتُ كَعْبٍ', 'ഉമ്മുഉമാറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ سَفِينَةَ رَضِيَ اللهُ عَنْهَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ بِالْمُدِّ، وَيَغْتَسِلُ بِالصَّاعِ. (م,ت,جه)', 'സഫീന(റ): നബി(സ) ഒരു മുദ്ദ് വെള്ളം കൊണ്ട് വുദൂ ചെയ്യുകയും ഒരു സ്വാഅ് വെള്ളം കൊണ്ട് കുളിക്കുകയും ചെയ്തിരുന്നു. (മു,തു,ജ)', 'سَفِينَةَ', 'സഫീന(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَقِيلِ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُجْزِئُ مِنَ الْوُضُوءِ مُدٌّ، وَمِنَ الْغُسْلِ صَاعٌ". فَقَالَ رَجُلٌ: لَا يُجْزِئُنَا. فَقَالَ: قَدْ كَانَ يُجْزِئُ مَنْ هُوَ خَيْرٌ مِنْكَ، وَأَكْثَرُ شَعْرًا يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. [ز: في إسناده ضعيف] (جه)', 'അഖീലുബ്നു അബീത്വാലിബ്(റ): നബി(സ) പറഞ്ഞു: വുളുവിന് ഒരു മുദ്ദ് വെള്ളവും, കുളിക്ക് ഒരു സ്വാഅ് വെള്ളവും മതിയാവും. അപ്പോൾ ഒരാൾ പറഞ്ഞു: ഞങ്ങൾക്കത് മതിയാവില്ല. നബി(സ) പറഞ്ഞു: "നിന്നേക്കാൾ ശ്രേഷ്ഠനും, കൂടുതൽ മുടിയുമുള്ള (നബി(സ)ക്ക്) ആൾക്കുവരെ അത് മതിയായിരിക്കുന്നു." ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'عَقِيلِ بْنِ أَبِي طَالِبٍ', 'അഖീലുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 162, 162, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا وُضُوءَ لِمَنْ لَمْ يَذْكُرِ اسْمَ اللهِ عَلَيْهِ". (جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമം ഉച്ചരിക്കാത്തവന്ന് വുദൂ ഇല്ല." (ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا صَلَاةَ لِمَنْ لَا وُضُوءَ لَهُ، وَلَا وُضُوءَ لِمَنْ لَمْ يَذْكُرِ اسْمَ اللهِ عَلَيْهِ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വുദൂ ഇല്ലാത്തവന്ന് നിസ്കാരമില്ല, അല്ലാഹുവിന്റെ നാമം ഉച്ചരിക്കാത്തവന്ന് വുദൂവുമില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا صَلَاةَ لِمَنْ لَا وُضُوءَ لَهُ، وَلَا وُضُوءَ لِمَنْ لَمْ يَذْكُرِ اسْمَ اللهِ عَلَيْهِ، وَلَا صَلَاةَ لِمَنْ لَا يُصَلِّي عَلَى النَّبِيِّ، وَلَا صَلَاةَ لِمَنْ لَا يُحِبُّ الْأَنْصَارَ". [ز: ضعيف] (جه)', 'സഹ്ലുസ്സാഇദീ(റ): നബി(സ) പറഞ്ഞു: "വുദൂ ഇല്ലാത്തവന്ന് നിസ്കാരമില്ല, അല്ലാഹുവിന്റെ നാമം ഉച്ചരിക്കാത്തവന്ന് വുദൂവുമില്ല. നബി(സ)യുടെമേൽ സ്വാലത്ത് ചൊല്ലാത്തവനും, അൻസ്വാറുകളെ ഇഷ്ടപ്പെടാത്തവനും നിസ്കാരമില്ല." (ഹദീസ് ദുർബ്ബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുസ്സാഇദീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضعيف', 'ഹദീസ് ദുർബ്ബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു', 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: طَلَبَ بَعْضُ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَضُوءًا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مَعَ أَحَدٍ مِنْكُمْ مَاءٌ" فَوَضَعَ يَدَهُ فِي الْمَاءِ وَيَقُولُ: "تَوَضَّئُوا بِسْمِ اللهِ". فَرَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ. قِيلَ لِأَنَسٍ: كَمْ تُرَاهُمْ؟ قَالَ: نَحْوًا مِنْ سَبْعِينَ. (ن)', 'അനസ്(റ): നബി(സ)യുടെ അനുചരന്മാരിൽ ചിലർ വുദൂഇനു വെള്ളമന്വേഷിച്ചു, നബി(സ) ചോദിച്ചു: "നിങ്ങളിലാരുടെയെങ്കിലുമടുക്കൽ വെള്ളമുണ്ടോ?" നബി(സ) തന്റെ കൈ വെള്ളത്തിൽ വെച്ച ശേഷം പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമത്തിൽ നിങ്ങൾ വുദൂ ചെയ്യുക." അവസാനത്തെആളും വുദൂ ചെയ്തു തീരുംവരെ നബി(സ)യുടെ വിരലുകൾക്കിടയിൽ നിന്ന് വെള്ളം വരുന്നതായി ഞാൻ കണ്ടു. അനസ്(റ) പറഞ്ഞു: അവർ എഴുപതോളം പേരുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَوَضَّأْتُمْ فَابْدَءُوا بِمَيَامِنِكُمْ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വുദൂ ചെയ്യുമ്പോൾ വലത്തേതു കൊണ്ട് തുടങ്ങുക." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَضْمَضَ ثَلَاثًا، وَاسْتَنْشَقَ ثَلَاثًا مِنْ كَفٍّ وَاحِدٍ. (جه)', 'അലി(റ): നബി(സ) വുദൂ ചെയ്തു. ഒരേ കയ്യിൽ നിന്ന് മൂന്നു പ്രാവശ്യം വായിൽ വെള്ളം കൊപ്ലിക്കുകയും, മൂക്കിൽ കയറ്റിച്ചീറ്റുകയും ചെയ്തു. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 163, 163, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلْنَا وَضُوءًا، فَأَتَيْتُهُ بِمَاءٍ، فَمَضْمَضَ، وَاسْتَنْشَقَ مِنْ كَفٍّ وَاحِدٍ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നുൽ അൻസ്വാരി(റ): നബി(സ) ഞങ്ങളുടെ അടുത്തു വന്ന് വുദൂ ചെയ്യാൻ വെള്ളമാവശ്യപ്പെട്ടു. ഞാൻ വെള്ളമെടുത്തു കൊടുത്തു. ഒരേ കയ്യിൽ നിന്ന് വെള്ളമെടുത്ത് കൊപ്ലിക്കുകയും മൂക്കിൽ കയറ്റിച്ചീറ്റുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നുൽ അൻസ്വാരി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 163, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ تَوَضَّأَ وَاحِدَةً وَاحِدَةً. [ز: في إسناده واه] (جه)', 'ഉമർ(റ): നബി(സ) തബൂക്ക് യുദ്ധ വേളയിൽ ഓരോരോ പ്രാവശ്യമായി വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده واه', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ غُرْفَةً غُرْفَةً. (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഓരോ പ്രാവശ്യമായി വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ أَوْسِ بْنِ أَبِي أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَوْكَفَ ثَلَاثًا. (ن)', 'ഇബ്നുഔസ്(റ): നബി(സ) മൂന്നു പ്രാവശ്യം കഴുകാനാവശ്യപ്പെട്ടതായി ഞാൻ കണ്ടു. (ന)', 'ابْنِ أَوْسِ بْنِ أَبِي أَوْسٍ', 'ഇബ്നുഔസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ شَقِيقِ بْنِ سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عُثْمَانَ وَعَلِيًّا رضي الله عنهما- يَتَوَضَّآنِ ثَلَاثًا ثَلَاثًا، وَيَقُولَانِ: هَكَذَا كَانَ وُضُوءُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'ശഖീഖുബ്നു സലമ(റ): ഉസ്മാ(റ)നും അലി(റ)യും മൂന്നു പ്രാവശ്യം വീതം കഴുകി വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. അവർ രണ്ടുപേരും പറയാറുണ്ടായിരുന്നു: നബി(സ) ഇപ്രകാരമായിരുന്നു വുളൂ ചെയ്തിരുന്നത്. (ജ)', 'شَقِيقِ بْنِ سَلَمَةَ', 'ശഖീഖുബ്നു സലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ تَوَضَّأَ ثَلَاثًا ثَلَاثًا، وَرَفَعَ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن,جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം മൂന്നു പ്രാവശ്യം കഴുകി വുദൂ ചെയ്തു. ശേഷം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَائِشَةَ، وَأَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ ثَلَاثًا ثَلَاثًا. (جه)', 'ആഇശ, അബൂഹുറൈറ(റ): നബി(സ) മൂന്നു പ്രാവശ്യം വീതമായികഴുകി വുദൂ ചെയ്തു. (ജ)', 'عَائِشَةَ، وَأَبِي هُرَيْرَةَ', 'ആഇശ, അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ ثَلَاثًا ثَلَاثًا، وَمَسَحَ رَأْسَهُ مَرَّةً. [ز: في إسناده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ): ഞാൻ നബി(സ)യെ മൂന്നു പ്രാവശ്യം വീതം കഴുകി വുദൂ ചെയ്യുന്നത് കണ്ടു. അവർ തല ഒരു പ്രാവശ്യം തടവി. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമജാ പറയുന്നു) (ജ)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമജാ പറയുന്നു', 164, 164, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: تَوَضَّأَ ثَلَاثًا ثَلَاثًا، يُسْنَدُ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹം അവയവങ്ങൾ മുമ്മൂന്നു പ്രാവശ്യം കഴുകികൊണ്ട് വുദൂ ചെയ്തു. ഇക്കാര്യം നബി(സ)യിലേക്ക് ചേർത്തു പറയുകയും ചെയ്തു. (ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 164, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاحِدَةً وَاحِدَةً، فَقَالَ: "هَذَا وُضُوءُ مَنْ لَا يَقْبَلُ اللهُ مِنْهُ صَلَاةً إِلَّا بِهِ". ثُمَّ تَوَضَّأَ ثِنْتَيْنِ ثِنْتَيْنِ، فَقَالَ: "هَذَا وُضُوءُ الْقَدْرِ مِنَ الْوُضُوءِ". وَتَوَضَّأَ ثَلَاثًا ثَلَاثًا، وَقَالَ: "هَذَا أَسْبَغُ الْوُضُوءِ، وَهُوَ وُضُوئِي وَوُضُوءُ خَلِيلِ اللهِ إِبْرَاهِيمَ، وَمَنْ تَوَضَّأَ هَكَذَا، ثُمَّ قَالَ عِنْدَ فَرَاغِهِ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، فُتِحَ لَهُ ثَمَانِيَةُ أَبْوَابِ الْجَنَّةِ يَدْخُلُ مِنْ أَيِّهَا شَاءَ". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഓരോ പ്രാവശ്യം വീതമായി കഴുകി വുദൂ ചെയ്തു. ശേഷം പറഞ്ഞു: "അല്ലാഹു നിസ്കാരം സ്വീകരിക്കാൻ അത്യാവശ്യമായ വുദൂവാണിത്." പിന്നെ രണ്ട് പ്രാവശ്യം വീതം കഴുകി വുദൂ ചെയ്തു. പിന്നെ പറഞ്ഞു: "ഇത് വുദൂഇൽ മതിയായതാണ്". പിന്നെ മൂന്നുപ്രവശ്യം വീതം കഴുകി വുദൂ ചെയ്തു. ശേഷം പറഞ്ഞു: "ഇതാണ് പരിപൂർണ്ണമായ വുദൂ. എന്റെയും അല്ലാഹുവിന്റെയും കൂട്ടുകാരനായ ഇബ്രാഹീമിന്റെയും വുദൂവാണിത്. ഇങ്ങനെ വുദൂ ചെയ്യുകയും: അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ് നബി(സ) അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമനാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു എന്നു പറയുകയും ചെയ്താൽ സ്വർഗ്ഗത്തിലെ എട്ടു കവാടങ്ങൾ അവനായി തുറക്കപ്പെടുകയും അതിൽ ഇഷ്ടമുള്ളതിലൂടെ അവന് പ്രവേശിക്കുകയും ചെയ്യാവുന്നതാണ്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَعَا بِمَاءٍ فَتَوَضَّأَ مَرَّةً مَرَّةً، فَقَالَ: "هَذَا وَظِيفَةُ الْوُضُوءِ". أَوْ قَالَ: "وُضُوءُ مَنْ لَمْ يَتَوَضَّأْهُ لَمْ يَقْبَلِ اللهُ لَهُ صَلَاةً". ثُمَّ تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ، ثُمَّ قَالَ: "هَذَا وُضُوءُ، مَنْ تَوَضَّأَهُ أَعْطَاهُ اللهُ كِفْلَيْنِ مِنَ الْأَجْرِ". ثُمَّ تَوَضَّأَ ثَلَاثًا ثَلَاثًا، فَقَالَ: "هَذَا وُضُوئِي وَوُضُوءُ الْمُرْسَلِينَ مِنْ قَبْلِي". [ز: في إسناده ضعيف] (جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) വെള്ളം കൊണ്ടുവരാൻ പറയുകയും ഓരോ പ്രാവശ്യം വീതം കഴുകി വുദൂ ചെയ്യുകയും ചെയ്തു. പിന്നെ പറഞ്ഞു: "ഇതാണ് വുദൂവെന്ന ബാധ്യത." അല്ലെങ്കിൽ (റിപ്പോർട്ടറുടെ സംശയം) നബി(സ) പറഞ്ഞു: "ഇതൊരു വുദൂവാണ്, ഇതാരെങ്കിലും ചെയ്യാതിരുന്നാൽ അവന്റെ നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല." പിന്നെ രണ്ട് പ്രാവശ്യം വീതം വുദൂ ചെയ്തു." ശേഷം പറഞ്ഞു: "ഇതൊരു വുദൂവാണ്. ആരെങ്കിലും ഇപ്രകാരം വുളു ചെയ്താൽ അല്ലാഹു അവന്ന് പ്രതിഫലത്തിൽ നിന്ന് രണ്ടോഹരി നൽകും." പിന്നെ മൂന്നു പ്രവശ്യം വീതം കഴുകികൊണ്ട് വുദൂ ചെയ്തു. ശേഷം പറഞ്ഞു: "ഇതാണ് എന്റെയും മുൻകഴിഞ്ഞ പ്രവാചകന്മാരുടെയും വുദൂ." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ عَنِ الْوُضُوءِ فَأَرَاهُ ثَلَاثًا ثَلَاثًا، ثُمَّ قَالَ: "هَذَا الْوُضُوءُ، فَمَنْ زَادَ عَلَى هَذَا فَقَدْ أَسَاءَ. أَوْ تَعَدَّى، أَوْ ظَلَمَ". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരു അഅ്റാബി (കാട്ടറബി) നബി(സ)യുടെഅടുത്തുവന്ന് വുദൂവിനെപ്പറ്റി ചോദിച്ചു. നബി(സ) അയാൾക്ക് മൂന്നുപ്രവശ്യം വീതം കഴുകികൊണ്ട് വുദൂ ചെയ്തു കാണിച്ചു കൊടുത്തു. പിന്നെ പറഞ്ഞു: "ഇതാണ് വുദൂ, ആരെങ്കിലും ഇതിൽ അധികരിപ്പിച്ചാൽ അവൻ തെറ്റു ചെയ്തിരിക്കുന്നു. അല്ലെങ്കിൽ പരിധി വിട്ടിരിക്കുന്നു. അല്ലെങ്കിൽ അതിക്രമം പ്രവർത്തിച്ചിരിക്കുന്നു." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 165, 165, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَتَوَضَّأَ مِنْ شَنَّةٍ وُضُوءًا يُقَلِّلُهُ، فَقُمْتُ فَصَنَعْتُ كَمَا صَنَعَ. (ق,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ എന്റെ മാതൃസഹോദരി മൈമൂന(റ)യുടെ അടുക്കൽ ഒരു രാത്രി താമസിച്ചു. നബി(സ) എഴുന്നേറ്റ് ഒരു തോൽപാത്രത്തിൽ നിന്ന് ചെറിയ തോതിൽ വുദൂ ചെയ്തു. ഞാനും എഴുന്നേറ്റ് നബി(സ) ചെയ്തതുപോലെ ചെയ്തു. (ബു,മു,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يَتَوَضَّأُ فَقَالَ: "لَا تُسْرِفْ، لَا تُسْرِفْ". [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): വുദൂ ചെയ്യുന്ന ഒരാളെ കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അമിതത്വം ഒഴിവാക്കുക, നീ അമിതത്വം ഒഴിവാക്കുക." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِسَعْدٍ وَهُوَ يَتَوَضَّأُ، فَقَالَ: "مَا هَذَا السَّرَفُ" فَقَالَ: أَفِي الْوُضُوءِ إِسْرَافٌ؟ قَالَ: "نَعَمْ وَإِنْ كُنْتَ عَلَى نَهْرٍ جَارٍ". [ز: في إسناده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): സഅദ്(റ) വുദൂ ചെയ്യുമ്പോൾ അദ്ദേഹത്തിനരികിലൂടെ നബി(സ) നടന്നു. നബി(സ) ചോദിച്ചു: "എന്താണീ അമിതത്വം?" അദ്ദേഹം ചോദിച്ചു: വുദൂവിൽ അമിതത്വമുണ്ടോ? നബി(സ) പറഞ്ഞു: "അതെ, നീ ഒഴുകിപ്പോവുന്ന പുഴക്കരികിലാണെങ്കിലും ശരി." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَحَانَتْ صَلَاةُ الْعَصْرِ، فَالْتَمَسَ النَّاسُ الْوَضُوءَ فَلَمْ يَجِدُوهُ، فَأُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ، فَوَضَعَ يَدَهُ فِي ذَلِكَ الْإِنَاءِ، وَأَمَرَ النَّاسَ أَنْ يَتَوَضَّئُوا، فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ، حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ. (ق,ت,ن)', 'അനസ്(റ): അസ്വർ നിസ്കാര സമയമായപ്പോൾ ഞാൻ നബി(സ)യെ കണ്ടു. ആളുകൾ വുദൂവിന്നുള്ള വെള്ളമന്വേഷിക്കുന്നു. അവർക്കാണെങ്കിൽ അതു കിട്ടിയിട്ടുമില്ല. അപ്പോൾ നബി(സ)ക്ക് അല്പം വെള്ളം കൊണ്ടുവരപ്പെട്ടു. നബി(സ) അതിൽ തന്റെ കൈ വെച്ച് ആളുകളോട് വുദൂ ചെയ്യാൻ പറഞ്ഞു. നബി(സ)യുടെ വിരലുകൾക്കിടയിലൂടെ വെള്ളം നിർഗ്ഗളിക്കുന്നതായി ഞാൻ കണ്ടു. അവസാനത്തേയാളും അതിൽ നിന്ന് വുദൂ ചെയ്തു. (ബു,മു,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَجِدُوا مَاءً، فَأُتِيَ بِتَوْرٍ فَأَدْخَلَ يَدَهُ، فَلَقَدْ رَأَيْتُ الْمَاءَ يَتَفَجَّرُ مِنْ بَيْنِ أَصَابِعِهِ، وَيَقُولُ: "حَيَّ عَلَى الطَّهُورِ وَالْبَرَكَةِ مِنَ اللهِ عَزَّ وَجَلَّ". قِيلَ لِجَابِرٍ: كَمْ كُنْتُمْ يَوْمَئِذٍ؟ قَالَ: أَلْفٌ وَخَمْسُ مِائَةٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമായിരിക്കെ വുദൂവിനു വെള്ളം ലഭിച്ചില്ല. അപ്പോൾ ഒരു പാത്രം കൊണ്ടുവരപ്പെട്ടു. നബി(സ) അതിൽ തന്റെ വിരലുകൾ വെച്ചു. തിരുമേനി(സ)യുടെ കൈവിരലുകൾക്കിടയിലൂടെ വെള്ളം പൊട്ടിയൊഴുകുന്നതായി ഞാൻ കണ്ടു. നബി(സ) ഇപ്രകാരം പറയുന്നുണ്ടയിരുന്നു: "പ്രതാപശാലിയായ അല്ലാഹുവിൽ നിന്നുള്ള അനുഗ്രഹത്തിലേക്കും സംശുദ്ധിയിലേക്കും കടന്നു വരുവിൻ." ജാബിറി(റ)നോട് ചോദിക്കപ്പെട്ടു: അവർ എത്ര പേരുണ്ടായിരുന്നു? അദ്ദേഹം പറഞ്ഞു: ആയിരത്തഞ്ഞൂറ് പേരുണ്ടായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 166, 166, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ – صَاحِبِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: أَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْرَجْنَا لَهُ مَاءً فِي تَوْرٍ مِنْ صُفْرٍ، فَتَوَضَّأَ بِهِ. (جه)', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): നബി(സ) ഞങ്ങളുടെയടുത്തു വന്നപ്പോൾ മഞ്ഞച്ചെമ്പിനാലുള്ള ഒരു (പാന) പാത്രത്തിൽ വെള്ളം നൽകകുയും അതിൽ നിന്ന് വുദൂ ചെയ്യുകയും ചെയ്തു. (ജ)', 'عَبْدِ اللهِ بْنِ زَيْدٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهُ كَانَ لَهَا مِخْضَبٌ مِنْ صُفْرٍ، قَالَتْ: فَكُنْتُ أُرَجِّلُ رَأْسَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيهِ. (جه)', 'സൈനബ് ബിൻത് ജഹ്ശ്(റ): മഞ്ഞച്ചെമ്പിനാൽ നിർമ്മിതമായ ഒരു തളിക അവർക്കുണ്ടായിരുന്നു. അവർ പറഞ്ഞു: ഞാൻ ആ പാത്രത്തിൽ വെച്ച് നബി(സ)യുടെ മുടി ചീകിക്കൊടുക്കാറുണ്ടായിരുന്നു. (ജ)', 'زَيْنَبَ بِنْتِ جَحْشٍ', 'സൈനബ് ബിൻത് ജഹ്ശ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ فِي تَوْرٍ. (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു പാനപാത്രത്തിൽ നിന്ന് വുദൂ ചെയ്യാറുണ്ടായിരുന്നു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ الْمُغِيرَةِ رَضِيَ اللهُ عَنْهُ قَالَ: سَكَبْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ تَوَضَّأَ فِي غَزْوَةِ تَبُوكَ، فَمَسَحَ عَلَى الْخُفَّيْنِ. (ن)', 'മുഗീറ(റ): നബി(സ) തബൂക്കിൽ വെച്ച് വുദൂ ചെയ്തപ്പോൾ ഞാൻ നബിക്ക് വെള്ളമൊഴിച്ചു കൊടുത്തു. നബി(സ) തന്റെ ഖുഫ്ഫ തടവി. (ന)', 'الْمُغِيرَةِ', 'മുഗീറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللهُ تَعَالَى، فَالصَّلَوَاتُ الْمَكْتُوبَاتُ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ". (م)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹു കൽപിച്ചപോലെ നന്നായി വുദൂ ചെയ്താൽ ഫർദ് നിസ്കാരങ്ങൾ അവക്കിടയിലുള്ളതിന്റെ പ്രായശ്ചിത്തമാണ്." (മു)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِإِسْبَاغِ الْوُضُوءِ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഞങ്ങളോട് പൂർണ്ണമായി വുദൂ ചെയ്യാൻ കൽപിച്ചു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 167, 167, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللهُ بِهِ الْخَطَايَا وَيَزِيدُ بِهِ فِي الْحَسَنَاتِ؟". قَالُوا: بَلَى يَا رَسُولَ اللهِ، قَالَ: "إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ". (جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അല്ലാഹു തെറ്റുകൾ പൊറുക്കുകയും നന്മകൾ വർദ്ധിപ്പിക്കുകയും ചെയ്യുന്ന ഒരുകാര്യം ഞാൻ അറിയിച്ചു തരട്ടെയോ?" അവർ പറഞ്ഞു: അതെ റസൂലേ! അപ്പോൾ നബി(സ) പറഞ്ഞു: "വുദൂ ചെയ്യാൻ പ്രയാസമുണ്ടായിരിക്കെ (തണുപ്പും മറ്റു പ്രയാസങ്ങളും ഉള്ളപ്പോഴും) പൂർണ്ണമായി വുദൂ ചെയ്യുക, പള്ളിയിലേക്കു കാലടി വർദ്ധിപ്പിക്കുക, ഒരു നിസ്കാരശേഷം അടുത്ത നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുക." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 167, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَفَّارَاتُ الْخَطَايَا: إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَإِعْمَالُ الْأَقْدَامِ إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ദോഷങ്ങളെ പൊറുപ്പിക്കുന്ന കാര്യങ്ങൾ വെറുപ്പുള്ള സമയത്ത് പൂർണ്ണമായി വുദൂ ചെയ്യൽ, പള്ളിയിലേക്കു കാലടി വർദ്ധിപ്പിക്കൽ, ഒരു നിസ്കാരശേഷം അടുത്ത നിസ്കാരം പ്രതീക്ഷിക്കൽ എന്നിവയാകുന്നു." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إذا شرب – وفي رِوَايَةٍ: وَلَغَ – الْكَلْبُ في إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ". (ق,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നായ നിങ്ങളുടെ പാത്രത്തിൽ തലയിട്ടാൽ- ഒരു റിപ്പോർട്ടിൽ: പാത്രത്തിൽ നിന്നും കുടിച്ചാൽ - ആ പാത്രം ഏഴു തവണ കഴുകേണ്ടതാണ്." (ബു,മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=11 and h.hadith_no=71), 1, 'وَفِي رِوَايَةٍ: وَلَغَ – الْكَلْبُ في إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ". (ق,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا مُنَادِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ اللهَ وَرَسُولَهُ يَنْهَاكُمْ عَنْ لُحُومِ الْحُمُرِ، فَإِنَّهَا رِجْسٌ. (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ അറിയിപ്പുകാരൻ ഞങ്ങളുടെയടുക്കൽ വന്നുപറഞ്ഞു: അല്ലാഹുവും അല്ലാഹുവിന്റെ ദൂതനും നിങ്ങളെ കഴുതമാംസം ഭക്ഷിക്കുന്നതിൽ നിന്നും നിരോധിച്ചിരിക്കുന്നു. കാരണം അത് നജസാകുന്നു. (ന)', 'أَنَسٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ– وَكَانَتْ عِنْدَ ابْنِ أَبِي قَتَادَةَ، أَنَّ أَبَا قَتَادَةَ دَخَلَ عَلَيْهَا، قَالَتْ: فَسَكَبْتُ لَهُ وَضُوءًا، قَالَتْ: فَجَاءَتْ هِرَّةٌ تَشْرَبُ، فَأَصْغَى لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ، قَالَتْ كَبْشَةُ: فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ: أَتَعْجَبِينَ يَا بِنْتَ أَخِي؟ فَقُلْتُ: نَعَمْ، قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنَ الطَّوَّافِينَ عَلَيْكُمْ أَوِ الطَّوَّافَاتِ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'കബ്ശ(റ): അബൂഖതാദ(റ) അവരുടെ അടുക്കൽ കടന്നു ചെന്നു. അപ്പോൾ അവർ അദ്ദേഹത്തിന് വുദൂ ചെയ്യാനുള്ള വെള്ളം ഒഴിച്ചു കൊടുത്തു. അപ്പോൾ ഒരു പൂച്ച വന്ന് അതിൽ നിന്നും വെള്ളം കുടിക്കാൻ വന്നു. അപ്പോൾ അദ്ദഹം പാത്രം താഴ്ത്തി കൊടുക്കുകയും അത് വെള്ളം കുടിക്കുകയും ചെയ്തു. നിവേദകയായ കബ്ശ(റ) പറയുന്നു: അന്നേരം ഞാൻ അദ്ദേഹത്തിലേക്ക് നോക്കുന്നതായി അദ്ദേഹം കണ്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദര പുത്രീ! നീ അത്ഭുതം പ്രകടിപ്പികുയാണോ? ഞാൻ പറഞ്ഞു: അതെ, അദ്ദേഹം പറഞ്ഞു അല്ലാഹുവിന്റെ റസൂൽ(സ) (പൂച്ചയെ സംബന്ധിച്ച്) ഇപ്രകാരം പറഞ്ഞിട്ടുണ്ട്: നിശ്ചയം അവ അശുദ്ധമല്ല. അവ നിങ്ങളെ ചുറ്റിപ്പറ്റി ജീവിക്കുന്നവയാണ്. (തു,ന,ദ,ജ)', 'كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ– وَكَانَتْ عِنْدَ ابْنِ أَبِي قَتَادَةَ، أَنَّ أَبَا قَتَادَةَ دَخَلَ عَلَيْهَا، قَالَتْ', 'കബ്ശ(റ)', null, null, array['ت']::text[], array['തു','ന','ദ','ജ']::text[], null, null, 168, 168, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ دَاوُدَ بْنِ صَالِحِ بْنِ دِينَارٍ التَّمَّارِ، عَنْ أُمِّهِ: أَنَّ مَوْلَاتَهَا أَرْسَلَتْهَا بِهَرِيسَةٍ إِلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَوَجَدْتُهَا تُصَلِّي، فَأَشَارَتْ إِلَيَّ: أَنْ ضَعِيهَا، فَجَاءَتْ هِرَّةٌ فَأَكَلَتْ مِنْهَا، فَلَمَّا انْصَرَفَتْ أَكَلَتْ مِنْ حَيْثُ أَكَلَتِ الْهِرَّةُ، فَقَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنَ الطَّوَّافِينَ عَلَيْكُمْ" وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ بِفَضْلِهَا. (د)', 'ദാവൂദ്ബിനു സാലിഹ്(റ): തന്റെ മാതാവിൽനിന്ന്: അവരുടെ യജമാനത്തി അവരെ ആഇശ(റ)യുടെ അടുക്കലേക്ക് പായസവുമായി അയച്ചു. അപ്പോൾ അവർ (ആഇശ) നിസ്കരിക്കുന്നതായി അവർ കണ്ടു. ''അവിടെ വെച്ചുകൊള്ളുക!'' എന്ന് അവർ ആംഗ്യത്തിലൂടെ നിർദ്ദേശിച്ചു. അങ്ങിനെ ഒരു പൂച്ച വന്ന് അതിൽ നിന്നും തിന്നു. അത് തിരിഞ്ഞു പോയപ്പോൾ പൂച്ച തിന്ന ഭാഗത്തുനിന്നും തന്നെ ആഇശ(റ)യും കഴിച്ചു. ശേഷം അവർ പറഞ്ഞു: നിശ്ചയം, അവ അശുദ്ധമല്ല, അവ നിങ്ങളെ ചുറ്റിപ്പറ്റി ജീവിക്കുന്നവയാണ്. നബി(സ) അവയുടെ ബാക്കി കൊണ്ടു വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ)', 'دَاوُدَ بْنِ صَالِحِ بْنِ دِينَارٍ التَّمَّارِ، عَنْ أُمِّهِ', 'ദാവൂദ്ബിനു സാലിഹ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَتَعَرَّقُ الْعَرْقَ، فَيَضَعُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاهُ حَيْثُ وَضَعْتُ وَأَنَا حَائِضٌ، وَكُنْتُ أَشْرَبُ مِنَ الْإِنَاءِ فَيَضَعُ فَاهُ حَيْثُ وَضَعْتُ وَأَنَا حَائِضٌ. (ن)', 'ആഇശ(റ): ഞാൻ എല്ലിൽ നിന്നു മാംസം ഭക്ഷിക്കുമ്പോൾ നബി(സ) ആർത്തവകാരിയായ ഞാൻ വായ വെച്ചിടത്തുതന്നെ വായ വെച്ച് തിന്നുകയും, ഞാൻ കുടിക്കുമ്പോൾ എന്റെ വായ വെച്ചിടത്തുതന്നെ വായ വെച്ച് കുടിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تَغْتَسِلُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْإِنَاءِ الْوَاحِدِ. (ن)', 'ആഇശ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഒരേ പാത്രത്തിൽ നിന്നു കുളിക്കാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ قَالَ: قُلْتُ لِابْنِ عُمَرَ: رَأَيْتُكَ تَلْبَسُ هَذِهِ النِّعَالَ السِّبْتِيَّةَ وَتَتَوَضَّأُ فِيهَا؟ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُهَا وَيَتَوَضَّأُ فِيهَا. (ن)', 'ഉബൈദുബ്നു ജുറൈഹ്(റ): ഞാൻ ഇബ്നുഉമറി(റ)നോട് ചോദിച്ചു: നിങ്ങൾ തുകൽ ചെരിപ്പു ധരിച്ച് വുളു ചെയ്യുന്നുവല്ലോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. (ന)', 'عُبَيْدِ بْنِ جُرَيْجٍ قَالَ', 'ഉബൈദുബ്നു ജുറൈഹ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللهُ، فَالصَّلَاةُ الْمَكْتُوبَاتُ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ". (م,ن,جه)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു കൽപിച്ചപോലെ വുദൂ ചെയ്തു നിസ്കരിച്ചാൽ നിർബന്ധ നിസ്കാരങ്ങൾക്കിടക്കുള്ള തെറ്റുകൾ പൊറുക്കപ്പെടുന്നതാണ്." (മു,ന,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 169, 169, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ جَالِسًا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّهَا لَا تَتِمُّ صَلَاةٌ لِأَحَدٍ حَتَّى يُسْبِغَ الْوُضُوءَ كَمَا أَمَرَهُ اللهُ تَعَالَى: يَغْسِلُ وَجْهَهُ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ، وَيَمْسَحُ بِرَأْسِهِ، وَرِجْلَيْهِ إِلَى الْكَعْبَيْنِ". (د,ت,ن,جه)', 'റിഫാഅതുബ്നു റാഫിഅ്(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പമിരിക്കുമ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ കൽപനപ്രകാരം വുദൂ ചെയ്യാത്തവന്റെ ഒരു നിസ്കാരവും പരിപൂർണ്ണമാവുകയില്ല. (അതായത്) മുഖവും, കൈമുട്ടുവരെ ഇരുകൈകളും കഴുകൽ. തല തടവൽ, കാൽ ഞെരിയാണിവരെ കഴുകൽ." (ദ,തു,ന,ജ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'റിഫാഅതുബ്നു റാഫിഅ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 170, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ الْحُسَيْنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا قَالَ: دَعَانِي أَبِي عَلِيٌّ بِوَضُوءٍ، فَقَرَّبْتُهُ لَهُ، فَبَدَأَ فَغَسَلَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ قَبْلَ أَنْ يُدْخِلَهُمَا فِي وَضُوئِهِ، ثُمَّ مَضْمَضَ ثَلَاثًا وَاسْتَنْثَرَ ثَلَاثًا، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ، ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا، ثُمَّ الْيُسْرَى كَذَلِكَ، ثُمَّ مَسَحَ بِرَأْسِهِ مَسْحَةً وَاحِدَةً، ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى إِلَى الْكَعْبَيْنِ ثَلَاثًا، ثُمَّ الْيُسْرَى كَذَلِكَ، ثُمَّ قَامَ قَائِمًا فَقَالَ: نَاوِلْنِي. فَنَاوَلْتُهُ الْإِنَاءَ الَّذِي فِيهِ فَضْلُ وَضُوئِهِ، فَشَرِبَ مِنْ فَضْلِ وَضُوئِهِ قَائِمًا، فَعَجِبْتُ فَلَمَّا رَآنِي قَالَ: لَا تَعْجَبْ، فَإِنِّي رَأَيْتُ أَبَاكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ مِثْلَ مَا رَأَيْتَنِي صَنَعْتُ، يَقُولُ لِوُضُوئِهِ هَذَا وَشُرْبِ فَضْلِ وَضُوئِهِ قَائِمًا. (ن)', 'ഹുസൈൻ(റ): എന്റെ പിതാവ് അലി(റ) എന്നെ വിളിച്ചു. ഞാനദ്ദേഹത്തിൻടുത്തു ചെന്നപ്പോൾ അദ്ദേഹം വുദൂ ചെയ്യാനാരംഭിച്ചു. കൈകൾ വെള്ളത്തിൽ പ്രവേശിപ്പിക്കുന്നതിനു മുമ്പ് മുമ്മൂന്നു പ്രാവശ്യം കഴുകി. മൂന്നു തവണ മൂക്കിലും വായിലും വെള്ളം കൊണ്ടു. പിന്നെ മുഖം, മുഴം കൈകൾ എന്നിവ മൂന്നു പ്രാവശ്യം കഴുകി. ഒരു തവണ തല തടവി. ശേഷം ഇരുകാലുകളും ഞെരിയാണി വരെ മൂന്നു പ്രാവശ്യം വീതം കഴുകി. പിന്നെ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: ആ പാത്രമെനിക്കു തരിക! വെള്ളത്തിന്റെ ബാക്കിയുണ്ടായിരുന്ന ആ പാത്രം ഞാനദ്ദേഹത്തിന് നൽകിയപ്പോൾ അദ്ദേഹമത് കുടിച്ചു. ഞാൻ അത്ഭുതപ്പെട്ടു. എന്റെ ഉത്കണ്ഠ കണ്ട പിതാവ് പറഞ്ഞു: നീ അത്ഭുതപ്പെടണ്ടതില്ല, നീ എന്നെ കണ്ടപോലെ നിന്റെ പിതാവായ നബി(സ) ഇപ്രകാരം ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. അദ്ദഹം ഇപ്രകാരം വുദൂ ചെയ്തതിനെയും ബാക്കി നിന്ന് കുടിച്ചതിനെപ്പറ്റിയുമാണ് അദ്ദേഹം ഈ പറഞ്ഞത്. (ന)', 'الْحُسَيْنِ بْنِ عَلِيٍّ', 'ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 170, 170, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنِ الْمُغِيرَةِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَقَرَعَ ظَهْرِي بِعَصًا كَانَتْ مَعَهُ، فَعَدَلَ وَعَدَلْتُ مَعَهُ، حَتَّى أَتَى كَذَا وَكَذَا مِنَ الْأَرْضِ فَأَنَاخَ ثُمَّ انْطَلَقَ، قَالَ: فَذَهَبَ حَتَّى تَوَارَى عَنِّي، ثُمَّ جَاءَ فَقَالَ: "أَمَعَكَ مَاءٌ". وَمَعِي سَطِيحَةٌ لِي، فَأَتَيْتُهُ بِهَا فَأَفْرَغْتُ عَلَيْهِ، فَغَسَلَ يَدَيْهِ وَوَجْهَهُ، وَذَهَبَ لِيَغْسِلَ ذِرَاعَيْهِ– وَعَلَيْهِ جُبَّةٌ شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ– فَأَخْرَجَ يَدَهُ مِنْ تَحْتِ الْجُبَّةِ، فَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ، وَذَكَرَ مِنْ نَاصِيَتِهِ شَيْئًا وَعِمَامَتِهِ شَيْئًا، ثُمَّ مَسَحَ عَلَى خُفَّيْهِ، ثُمَّ قَالَ: "حَاجَتَكَ". قُلْتُ: يَا رَسُولَ اللهِ، لَيْسَتْ لِي حَاجَةٌ. فَجِئْنَا وَقَدْ أَمَّ النَّاسَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ، وَقَدْ صَلَّى بِهِمْ رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ، فَذَهَبْتُ لِأُوذِنَهُ فَنَهَانِي، فَصَلَّيْنَا مَا أَدْرَكْنَا وَقَضَيْنَا مَا سُبِقْنَا. (ن)', 'മുഗീറ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ അവിടുന്ന് എന്റെ മുതുകിൽ ഒരു വടി കൊണ്ട് (മെല്ലെ) അടിച്ചു. എന്നിട്ട് തിരുമേനി വഴിതിരിഞ്ഞു. ഞാനും കൂടെ തിരിഞ്ഞു. അങ്ങനെ ഇന്നാലിന്ന സ്ഥലത്ത് എത്തിയപ്പോൾ ഒട്ടകത്തെ നിർത്തി. ശേഷം നബി(സ) പോയി. പിന്നെ തിരിച്ചു വന്നു. എന്നിട്ട് ചോദിച്ചു: "നിന്റെടുത്ത് വെള്ളമുണ്ടോ?" എന്റടുത്തുണ്ടായിരുന്ന തോൽപാത്രത്തിലെ വെള്ളം ഞാൻ നബി(സ)ക്ക് ഒഴിച്ചുകൊടുത്തു. നബി(സ) തന്റെ മുഖവും കൈകളും കഴുകി, മുഴംകൈ കഴുകാനൊരുങ്ങിയപ്പോൾ - നബി(സ) മുൻകൈകൾ കുടുസ്സായ ഒരു ശാമീജുബ്ബ ധരിച്ചിരുന്നു- നബി കൈ ജുബ്ബയുടെ താഴ്ഭാഗത്തു കൂടെ പുറത്തെടുത്ത് മുഖവും രണ്ട് മുഴംകൈകളും കഴുകി. പിന്നെ തിരുമേനി(സ) തന്റെ ഇരു ഖുഫ്ഫകളും തടവി. പിന്നെ ചോദിച്ചു: "നിനക്കു വല്ല ആവശ്യവുമുണ്ടോ?" ഞാൻ പറഞ്ഞു: ''ഇല്ല''. അങ്ങനെ ഞങ്ങൾ തിരിച്ചുവന്നു. അപ്പോൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) നിസ്കാരത്തിന് നേതൃത്വം നൽകുന്നുണ്ടായിരുന്നു. സുബ്ഹിയുടെ ഒരു റക്അത്ത് അദ്ദേഹം ജനങ്ങളോടൊപ്പം നിർവ്വഹിച്ചിട്ടുണ്ടായിരുന്നു. ഞാൻ ബാങ്കു വിളിക്കാനൊരുങ്ങിയപ്പോൾ നബി(സ) എന്നെ വിലക്കി. (ഇമാമിനോടൊപ്പം) ഞങ്ങൾ കിട്ടിയതു നിസ്കരിച്ചു, നഷ്ടപ്പെട്ടതു വീട്ടി. (ന)', 'الْمُغِيرَةِ', 'മുഗീറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 170, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَخَلَّلَ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ. (د,ت,جه)', 'മുസ്തൗരിദ്ബ്നു ശദ്ദാദ്(റ): നബി(സ) വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. രണ്ട് കാൽവിരലുകളെ ചെറുവിരലുപയോഗിച്ച് തിക്കകെറ്റുകയും ചെയ്തു. (ദ,തു,ജ)', 'الْمُسْتَوْرِدِ بْنِ شَدَّادٍ', 'മുസ്തൗരിദ്ബ്നു ശദ്ദാദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قُمْتَ إِلَى الصَّلَاةِ فَأَسْبِغِ الْوُضُوءَ، وَاجْعَلِ الْمَاءَ بَيْنَ أَصَابِعِ يَدَيْكَ وَرِجْلَيْكَ". (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിനൊരുങ്ങുമ്പോൾ പൂർണ്ണമായി നന്നായി വുദൂ ചെയ്യുക. വെള്ളം കൈകാൽ വിരലുകൾക്കിടയിലാക്കുക." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ لَقِيطِ بْنِ صَبْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " أَسْبِغِ الْوُضُوءَ، وَخَلِّلْ بَيْنَ الْأَصَابِعِ". (د,ت,ن,جه)', 'ലഖീതുബ്നുസ്വബ്റ(റ): നബി(സ) പറഞ്ഞു : "വുദൂ പൂർണ്ണമായി ചെയ്യുക. വിരലുകൾക്കിടയിൽ തിക്കകെറ്റുക." (ദ,തു,ന,ജ)', 'لَقِيطِ بْنِ صَبْرَةَ', 'ലഖീതുബ്നുസ്വബ്റ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَوَضَّأَ حَرَّكَ خَاتَمَهُ. (جه)', 'അബൂറാഫിഅ്(റ): നബി(സ) വുദൂ ചെയ്യുമ്പോൾ തന്റെ മോതിരം(ധരിച്ച സ്ഥാനം നനക്കാൻ വേണ്ടി) ചലിപ്പിക്കാറുണ്ടായിരുന്നു.(ജ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 171, 171, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ، فَلَا يُدْخِلْ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉറക്കിൽ നിന്നെഴുന്നേറ്റാൽ അവന്റെ കൈ കഴുകുന്നതിനു മുമ്പ് പാത്രത്തിൽ ഇടരുത്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 171, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَامَ أَحَدُكُمْ مِنَ النَّوْمِ، فَأَرَادَ أَنْ يَتَوَضَّأَ، فَلَا يُدْخِلْ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا، فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ، وَلَا عَلَى مَا وَضَعَهَا". (جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉറക്കിൽ നിന്നെഴുന്നേറ്റ് വുദൂ ചെയ്യാനാഗ്രഹിച്ചാൽ അവന്റെ കൈ കഴുകുന്നതിനു മുമ്പ് പാത്രത്തിൽ ഇടരുത്. കാരണം, ഉറക്കിൽ അവന്റെ കൈ എവിടെയാണുണ്ടായിരുന്നതെന്നോ എവിടെയാണ് വെച്ചതെന്നോ അവനറിയില്ല." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّهُ دَعَا بِمَاءٍ، فَغَسَلَ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا الْإِنَاءَ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَنَعَ. (جه)', 'അലി(റ): അദ്ദേഹം വെള്ളം കൊണ്ടുവരാനാവശ്യപ്പെട്ടു. എന്നിട്ട് പാത്രത്തിൽ ഇടുന്നതിനു മുമ്പ് രണ്ട് കൈകളും കഴുകി. ശേഷം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യുന്നതു ഞാൻ കണ്ടിട്ടുണ്ട്. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ: تَوَضَّأَ: فَأَفْرَغَ عَلَى يَدَيْهِ ثَلَاثًا فَغَسَلَهُمَا، ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، ثُمَّ غَسَلَ يَدَيْهِ: الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا، ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ قَدَمَهُ الْيُمْنَى ثَلَاثًا، ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ، ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ نَحْوَ وُضُوئِي ثُمَّ قَالَ: "مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا، ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ نَفْسَهُ فِيهِمَا بِشَيْءٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ن)', 'ഉസ്മാൻ(റ): അദ്ദേഹം വുദൂ ചെയ്തപ്പോൾ മൂന്നുതവണ വെള്ളമൊഴിച്ചു കഴുകി. പിന്നെ വായിലും മൂക്കിലും വെള്ളം കൊണ്ടു, ശേഷം മൂന്നുതവണ മുഖം കഴുകി. ശേഷം കൈകളും: വലതുകൈ മുട്ടുവരെയും ഇടതു കയ്യും കഴുകി. പിന്നെ തല തടവി. പിന്നെ യഥാക്രമം വലതുകാൽ, ഇടതുകാൽ എന്നിവയും കഴുകി. എന്നിട്ട് പറഞ്ഞു: നബി(സ) ഇപ്രകാരം വുദൂ ചെയ്യുന്നതായി ഞാൻ കണ്ടു. നബി(സ) ഇങ്ങനെ പറഞ്ഞു: "ആരെങ്കിലും ഇപ്രകാരം വുദൂ ചെയ്ത് അശുദ്ധനാവാതെ രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ അവന്റെ മുൻപാപങ്ങളെല്ലാം പൊറുക്കപ്പെടുന്നതാണ്." (ന)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ سَلَمَةَ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَوَضَّأْتَ فَانْثُرْ، وَإِذَا اسْتَجْمَرْتَ فَأَوْتِرْ". (ت,ن,جه)', 'സലമതുബ്നു ഖൈസ്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "നീ വുളു ചെയ്യുമ്പോൾ മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുക. കല്ലുകൊണ്ട് ശൗച്യം ചെയ്യുകയാണെങ്കിൽ ഒറ്റയായ (എണ്ണം) കല്ലുകൾ ഉപയോഗിക്കുക." (തു,ന,ജ)', 'سَلَمَةَ بْنِ قَيْسٍ', 'സലമതുബ്നു ഖൈസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ لَقِيطِ بْنِ صَبْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَخْبِرْنِي عَنِ الْوُضُوءِ؟ قَالَ: "أَسْبِغِ الْوُضُوءَ، وَبَالِغْ فِي الِاسْتِنْشَاقِ، إِلَّا أَنْ تَكُونَ صَائِمًا". (د,ت,ن,جه)', 'ലഖീതുബ്നു സ്വബ്റത്(റ): ഞാൻ ചോദിച്ചു: നബിയെ, വുദൂ ഇനെക്കുറിച്ച് എനിക്ക് പറഞ്ഞു തന്നാലും!. നബി(സ) പറഞ്ഞു: "നീ അവയവങ്ങളിലെല്ലാം വെള്ളമെത്തത്തക്ക രീതിയിൽ നന്നായി വുദൂ ചെയ്യുക, നോമ്പുകാരനല്ലെങ്കിൽ നന്നായി മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുക." (ദ,തു,ന,ജ)', 'لَقِيطِ بْنِ صَبْرَةَ', 'ലഖീതുബ്നു സ്വബ്റത്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 172, 172, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْتَنْثِرُوا مَرَّتَيْنِ بَالِغَتَيْنِ أَوْ ثَلَاثًا". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മൂന്ന് പ്രാവശ്യമോ അല്ലെങ്കിൽ നന്നായി രണ്ട് പ്രാവശ്യമോ മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുക." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً، ثُمَّ لِيَسْتَنْثِرْ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും വുദൂ ചെയ്യുകയാണെങ്കിൽ അവൻ മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റിക്കൊള്ളട്ടെ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عُثْمَانَ رَضِيَ اللهُ عَنْهُ: دَعَا بِوَضُوءٍ، فَأَفْرَغَ عَلَى يَدَيْهِ مِنْ إِنَائِهِ فَغَسَلَهَا ثَلَاثَ مَرَّاتٍ، ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْوُضُوءِ، فَتَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مَرَّاتٍ، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ كُلَّ رِجْلٍ مِنْ رِجْلَيْهِ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وُضُوئِي هَذَا ثُمَّ قَالَ: "مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا، ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ، لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ بِشَيْءٍ، غَفَرَ اللهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ن)', 'ഉസ്മാൻ(റ): അദ്ദേഹം വുദൂ ചെയ്യാൻ വെള്ളമാവശ്യപ്പട്ടു. കൈകൾ മൂന്നു തവണ കഴുകി. തന്റെ വലതു കൈ വെള്ളത്തിൽ കടത്തി വായിലും മൂക്കിലും വെള്ളം കൊണ്ടു. ശേഷം മുഖവും മുട്ടോടുകൂടെ വലതു കൈകളും മൂന്നു തവണ കഴുകി. പിന്നെ തല തടവി. പിന്നെ ഇരുകാലുകളും മൂന്നുതവണ കഴുകി. പിന്നെ പറഞ്ഞു: നബി(സ) ഇപ്രകാരം വുദൂ ചെയ്യുന്നതായി ഞാൻ കണ്ടു. നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഇപ്രകാരം വുദൂ ചെയ്ത് അശുദ്ധനാവാതെ രണ്ട് റക്അത്ത് നിസ്കരിച്ചാൽ അവന്റെ മുൻപാപങ്ങളെല്ലാം പൊറുക്കപ്പെടുന്നതാണ്." (ന)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَتَوَضَّأَ فَلْيَسْتَنْثِرْ ثَلَاثَ مَرَّاتٍ، فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى خَيْشُومِهِ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഉറക്കമുണർന്ന് വുദൂ ചെയ്യുകയാണെങ്കിൽ മൂന്നു തവണ മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റട്ടെ. കാരണം, പിശാച് അവന്റെ മൂക്കിനുള്ളിൽ വസിക്കുന്നതാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَعَا بِوَضُوءٍ، فَتَمَضْمَضَ وَاسْتَنْشَقَ، وَنَثَرَ بِيَدِهِ الْيُسْرَى، فَفَعَلَ هَذَا ثَلَاثًا، ثُمَّ قَالَ: هَذَا طُهُورُ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അലി(റ): അദ്ദേഹം വുദൂ ചെയ്യാനുള്ള വെള്ളമാവശ്യപ്പെട്ടു, വായിലും മൂക്കിലും വെള്ളം കൊണ്ട്, ഇടതു കൈ കൊണ്ട് ചീറ്റി. ഇപ്രകാരം മൂന്നു തവണ ചെയ്തു. പിന്നെ പറഞ്ഞു: നബി(സ)യുടെ ശുദ്ധി(വുദു)യാണിത്. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 173, 173, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: وَقَدْ صَلَّى، فَدَعَا بِطَهُورٍ، فَقُلْنَا: مَا يَصْنَعُ بِهِ وَقَدْ صَلَّى؟ مَا يُرِيدُ إِلَّا لِيُعَلِّمَنَا. فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ وَطَسْتٍ، فَأَفْرَغَ مِنَ الْإِنَاءِ عَلَى يَدَيْهِ فَغَسَلَهَا ثَلَاثًا، ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا مِنَ الْكَفِّ الَّذِي يَأْخُذُ بِهِ الْمَاءَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا، وَيَدَهُ الشِّمَالَ ثَلَاثًا، وَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً، ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى ثَلَاثًا، وَرِجْلَهُ الشِّمَالَ ثَلَاثًا، ثُمَّ قَالَ: "مَنْ سَرَّهُ أَنْ يَعْلَمَ وُضُوءَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَهُوَ هَذَا". (ن)', 'അലി(റ): അദ്ദേഹം നിസ്കാരശേഷം വുദൂവിന് വെള്ളമാവശ്യപ്പെട്ടു. ഞങ്ങൾ പറഞ്ഞു: ''നിസ്കാരശേഷം എന്തിനാണു വെള്ളം? നമ്മെ പഠിപ്പിക്കലായിരിക്കും ഉദ്ദേശ്യം.'' അങ്ങനെ ഒരുപാത്രം വെള്ളവും മറ്റൊരു വലിയ പാത്രവും കൊണ്ടുവരപ്പെട്ടു. വെള്ളമൊഴിച്ച് തന്റെ കൈകൾ മൂന്നു തവണ കഴുകി. വെള്ളമെടുക്കുന്ന അതേ കൈകൊണ്ട് മൂന്നു തവണ മൂക്കിലും വായിലും വെള്ളം കൊണ്ടു. പിന്നെ മുഖം, വലതുകൈ, ഇടതുകൈ എന്നിവ മുമ്മൂന്നു പ്രാവശ്യം കഴുകി. ഒരു തവണ തല തടവി. ശേഷം വലതു കാൽ, ഇടതുകാൽ മൂന്നു പ്രാവശ്യം വീതം കഴുകി. പിന്നെ പറഞ്ഞു: ആർക്കെങ്കിലും നബി(സ)യുടെ വുളു മനസ്സിലാക്കുന്നതിൽ സന്തോഷമുണ്ടെങ്കിൽ അതിപ്രകാരമാണ്. (ന)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أُتِيَ بِكُرْسِيٍّ فَقَعَدَ عَلَيْهِ، ثُمَّ دَعَا بِتَوْرٍ فِيهِ مَاءٌ فَكَفَأَ عَلَى يَدَيْهِ ثَلَاثًا، ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ بِكَفٍّ وَاحِدٍ ثَلَاثَ مَرَّاتٍ، وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، وَأَخَذَ مِنَ الْمَاءِ فَمَسَحَ بِرَأْسِهِ– وَأَشَارَ شُعْبَةُ مَرَّةً– مِنْ نَاصِيَتِهِ إِلَى مُؤَخَّرِ رَأْسِهِ، ثُمَّ قَالَ: لَا أَدْرِي أَرَدَّهُمَا أَمْ لَا؟ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ قَالَ: مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى طُهُورِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَهَذَا طُهُورُهُ. (ن)', 'അലി(റ): തനിക്കു നൽകപ്പെട്ട കസേരയിലിരുന്ന് വെള്ളപ്പാത്രമാവശ്യപ്പെട്ടു. എന്നിട്ടത് മൂന്നുപ്രാവശ്യം കൈകളിൽ ചൊരിച്ചു. ഒരു കൈ കൊണ്ട് മൂന്നുതവണ മൂക്കിലും വായിലും വെള്ളം കൊണ്ടു. പിന്നെ മുഖം, മുഴംകൈകൾ എന്നിവ മുമ്മൂന്നു പ്രാവശ്യം കഴുകി. വെള്ളമെടുത്ത് -ശുഅ്ബ ഒരു തവണ സൂചിപ്പിച്ചു.- മൂർദ്ദാവു മുതൽ തലയുടെ പിൻവശം വരെ തടവി. പിന്നെ പറഞ്ഞു: അവരണ്ടും ആവർത്തിച്ചോ എന്നറിയില്ല. രണ്ടു കാലുകളും മുമ്മൂന്നു പ്രാവശ്യം കഴുകി. പിന്നെ അലി(റ) പറഞ്ഞു: നബി(സ)യുടെ ശുദ്ധി (വുദൂ) മനസ്സിലാക്കാൻ ആഗ്രഹിക്കുന്നവർക്കാണിത്. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَمَّارِ ابْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُخَلِّلُ لِحْيَتَهُ. (ت,جه)', 'അമ്മാറുബ്നു യാസിർ(റ): നബി(സ) താടി തിക്കകെറ്റുന്നതായി ഞാൻ കണ്ടു. (തു,ജ)', 'عَمَّارِ ابْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ فَخَلَّلَ لِحْيَتَهُ. (ت,جه)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): നബി(സ) വുദൂ ചെയ്തപ്പോൾ താടി തിക്കകെറ്റി. (തു,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 174, 174, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا تَوَضَّأَ خَلَّلَ لِحْيَتَهُ، وَفَرَّجَ أَصَابِعَهُ مَرَّتَيْنِ. [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) വുദൂ ചെയ്യുമ്പോൾ തന്റെ വിരലുകൾ വിടർത്തികൊണ്ട് രണ്ടു തവണ താടി തിക്കകെറ്റാറുണ്ടായിരുന്നു. വിരലുകൾ കൊണ്ട് താടിരോമങ്ങൾ അകറ്റാറുണ്ടായിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 174, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: دَعَا بِكُرْسِيٍّ فَقَعَدَ عَلَيْهِ، ثُمَّ دَعَا بِمَاءٍ فِي تَوْرٍ، فَغَسَلَ يَدَيْهِ ثَلَاثًا، ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ بِكَفٍّ وَاحِدٍ ثَلَاثًا، ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا، وَيَدَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ غَمَسَ يَدَهُ فِي الْإِنَاءِ فَمَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ قَالَ: مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى وُضُوءِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَهَذَا وُضُوءُهُ. (ن)', 'അലി(റ): അദ്ദേഹം ഒരു കസേര കൊണ്ടുവരാനാവശ്യപ്പെട്ടു. ശേഷം തന്റെ കൈകൾ മൂന്നു പ്രാവശ്യം കഴുകി. ഒരുകൈ കൊണ്ട് മൂന്നുതവണ മൂക്കിലും വായിലും വെള്ളം കൊണ്ടു. പിന്നെ മുഖം, മുഴംകൈകൾ എന്നിവ മൂന്നു പ്രാവശ്യം കഴുകി. കൈ പാത്രത്തിൽ മുക്കി തല തടവി. രണ്ടുകാലുകളും മുമ്മൂന്നു പ്രാവശ്യം കഴുകി. പിന്നെ പറഞ്ഞു: നബി(സ)യുടെ വുദൂ മനസ്സിലാക്കാനാഗ്രഹിക്കുന്നവർക്കാണിത്. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: تَوَضَّأَ فَغَسَلَ كَفَّيْهِ حَتَّى أَنْقَاهُمَا، ثُمَّ تَمَضْمَضَ ثَلَاثًا، وَاسْتَنْشَقَ ثَلَاثًا، وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ، ثُمَّ قَامَ فَأَخَذَ فَضْلَ طَهُورِهِ فَشَرِبَ وَهُوَ قَائِمٌ، ثُمَّ قَالَ: أَحْبَبْتُ أَنْ أُرِيَكُمْ كَيْفَ طُهُورُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت,ن)', 'അലി(റ): വുളു ചെയ്തപ്പോൾ കൈകൾ കഴുകി വൃത്തിയാക്കി. മൂക്കിലും വായിലും വെള്ളം കൊള്ളൽ, മുഖം, മുഴം കൈകൾ എന്നിവ കഴുകൽ തുടങ്ങിയവ മുമ്മൂന്നു പ്രാവശ്യം ചെയ്തു. ശേഷം തല തടവി. ഇരുകാലുകളും ഞെരിയാണിവരെ കഴുകി. പിന്നെ എഴുന്നേറ്റുനിന്ന് ബാക്കി വെള്ളം കുടിച്ചു. പിന്നെ പറഞ്ഞു: നബി(സ)യുടെ വുദൂ എങ്ങനെയായിരുന്നുവെന്നു നിങ്ങളെ കാണിക്കാൻ ഞാനിഷ്ടപ്പെട്ടു. (തു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ، فَمَسَحَ رَأْسَهُ مَرَّةً. (جه)', 'ഉസ്മാൻ(റ): നബി(സ) വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. തല ഒരു തവണയാണ് തടവിയിരുന്നത്. (ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَسَحَ رَأْسَهُ مَرَّةً. (جه)', 'അലി(റ): നബി(സ) ഒരു പ്രാവശ്യം തല തടവി. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَسَحَ رَأْسَهُ مَرَّةً. [ز: في إسناده ضعيف] (جه)', 'സലമതുബ്നുൽ അക്വഅ്(റ): നബി(സ) വുദൂ ചെയ്യുകയും തല ഒരു പ്രാവശ്യം തടവുകയും ചെയ്തു. (ജ) [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു]', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['جه']::text[], '{}'::text[], 'ز: في إسناده ضعيف', null, 175, 175, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ابْنِ عَفْرَاءَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَمَسَحَ رَأْسَهُ مَرَّتَيْنِ. (جه)', 'റുബയ്യിഉബിൻത് മുഅവ്വിദുബിനു അഫ്റാഅ(റ): നബി(സ) വുദൂ ചെയ്യുകയും തല രണ്ടുപ്രാവശ്യം തടവുകയും ചെയ്തു. (ജ)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ ابْنِ عَفْرَاءَ', 'റുബയ്യിഉബിൻത് മുഅവ്വിദുബിനു അഫ്റാഅ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَبِي عَبْدِ اللهِ سَالِمٍ سَبَلَانَ رَضِيَ اللهُ عَنْهُ – وَكَانَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا تَسْتَعْجِبُ بِأَمَانَتِهِ وَتَسْتَأْجِرُهُ فَأَرَتْنِي– قَالَ: كَيْفَ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَوَضَّأُ: فَتَمَضْمَضَتْ وَاسْتَنْثَرَتْ ثَلَاثًا، وَغَسَلَتْ وَجْهَهَا ثَلَاثًا، ثُمَّ غَسَلَتْ يَدَهَا الْيُمْنَى ثَلَاثًا وَالْيُسْرَى ثَلَاثًا، وَوَضَعَتْ يَدَهَا فِي مُقَدَّمِ رَأْسِهَا، ثُمَّ مَسَحَتْ رَأْسَهَا مَسْحَةً وَاحِدَةً إِلَى مُؤَخَّرِهِ، ثُمَّ أَمَرَّتْ يَدَهَا بِأُذُنَيْهَا، ثُمَّ مَرَّتْ عَلَى الْخَدَّيْنِ. قَالَ سَالِمٌ: كُنْتُ آتِيهَا مُكَاتَبًا مَا تَخْتَفِي مِنِّي، فَتَجْلِسُ بَيْنَ يَدَيَّ وَتَتَحَدَّثُ مَعِي، حَتَّى جِئْتُهَا ذَاتَ يَوْمٍ فَقُلْتُ: ادْعِي لِي بِالْبَرَكَةِ يَا أُمَّ الْمُؤْمِنِينَ. قَالَتْ: وَمَا ذَاكَ؟ قُلْتُ: أَعْتَقَنِي اللهُ، قَالَتْ: بَارَكَ اللهُ لَكَ، وَأَرْخَتِ الْحِجَابَ دُونِي، فَلَمْ أَرَهَا بَعْدَ ذَلِكَ الْيَوْمِ. (ن)', 'അബൂഅബ്ദില്ലാഹി സാലിം (റ) [ ആഇശ(റ) അദ്ദേഹത്തിന്റെ വിശ്വസ്ഥതയിൽ സന്തോഷിക്കുകയും അദ്ദേഹത്തിന് അഭയം നൽകുകയും ചെയ്തിരുന്നു] പറഞ്ഞു: ഒരു ദിവസം എന്നെ ആഇശ(റ) കണ്ടു. ഞാൻ ചോദിച്ചു: നബി(സ) എങ്ങനെയായിരുന്നു വുദൂ ചെയ്തിരുന്നത്? അപ്പോൾ ആഇശ(റ) മൂന്നുതവണ വായിലും മൂക്കിലും വെള്ളംകൊണ്ടു, മുഖം മൂന്നുതവണ കഴുകി, വലതുകൈ, ഇടതുകൈ എന്നിവ മുമ്മൂന്നു പ്രാവശ്യം കഴുകുകയും പിന്നെ തന്റ തലയുടെ മുൻഭാഗം മുതൽ പിൻഭാഗം വരെ ഒരു പ്രാവശ്യം തടവി. പിന്നെ തന്റെ കൈ ചെവിയിലൂടെയും കവിളിലൂടെയും ചലിപ്പിച്ചു ; സാലിം(റ)തുടർന്ന് പറയുന്നു: മോചനപത്രം എഴുതപ്പെട്ട ശേഷവും ഞാനവരുടെയടുത്തു ചെല്ലുകയും മറയില്ലാതെത്തന്നെ അവരെന്നോട് സംസാരിക്കുകയും എന്നോടൊപ്പമിരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഒരിക്കൽ ഞാൻ പറഞ്ഞു: എനിക്ക് അനുഗ്രഹത്തിനായി പ്രാർത്ഥിച്ചാലും. അവർ ചോദിച്ചു: എങ്ങനെയാണു വേണ്ടത്? ഞാൻ പറഞ്ഞു: അല്ലാഹു എന്നെ മോചിപ്പിക്കട്ടെ. അവർ പറഞ്ഞു: അല്ലാഹു നിന്നെ അനുഗ്രഹിക്കട്ടെ. അപ്പോൾ അവർ എന്റെ മുന്നിലുള്ള വിരി താഴ്ത്തിയിട്ടു. പിന്നീട് ഞാനവരെ കണ്ടിട്ടില്ല. (ന)', 'أَبِي عَبْدِ اللهِ سَالِمٍ سَبَلَانَ', 'അബൂഅബ്ദില്ലാഹി സാലിം (റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ: رَأَى رَجُلًا يَنْزِعُ خُفَّيْهِ لِلْوُضُوءِ، فَقَالَ لَهُ: امْسَحْ عَلَى خُفَّيْكَ وَعَلَى خِمَارِكَ وَبِنَاصِيَتِكَ، فَإِنِّي رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ عَلَى الْخُفَّيْنِ وَالْخِمَارِ. (جه)', 'സൽമാൻ(റ): വുളുവിന്നായി ഖുഫ്ഫ അഴിക്കുന്ന ഒരാളെ കണ്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിന്റെ ഖുഫ്ഫക്കു മുകളിലും, തലപ്പാവിലും, കുടുമയിലും തടവുക. കാരണം, നബി(സ) തലപ്പാവും ഖുഫ്ഫയും തടവുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَعَلَيْهِ عِمَامَةٌ قِطْرِيَّةٌ، فَأَدْخَلَ يَدَهُ مِنْ تَحْتِ الْعِمَامَةِ، فَمَسَحَ مُقَدَّمَ رَأْسِهِ، وَلَمْ يَنْقُضِ الْعِمَامَةَ. (د,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരു തലപ്പാവ് ധരിച്ച് വുദൂ ചെയ്യുന്നതു ഞാൻ കണ്ടു. നബി(സ) തലപ്പാവിന്നടിയിലൂടെ കൈ വെക്കുകയും, തലയുടെ മുൻഭാഗം തടവുകയും ചെയ്തു. എന്നാൽ തലപ്പാവെടുത്തു മാറ്റിയില്ല. (ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 176, 176, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَصْلَتَانِ لَا أَسْأَلُ عَنْهُمَا أَحَدًا بَعْدَ مَا شَهِدْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: كُنَّا مَعَهُ فِي سَفَرٍ، فَبَرَزَ لِحَاجَتِهِ، ثُمَّ جَاءَ فَتَوَضَّأَ وَمَسَحَ بِنَاصِيَتِهِ وَجَانِبَيْ عِمَامَتِهِ، وَمَسَحَ عَلَى خُفَّيْهِ قَالَ: وَصَلَاةُ الْإِمَامِ خَلْفَ الرَّجُلِ مِنْ رَعِيَّتِهِ، فَشَهِدْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ فِي سَفَرٍ، فَحَضَرَتِ الصَّلَاةُ، فَاحْتَبَسَ عَلَيْهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَقَامُوا الصَّلَاةَ وَقَدَّمُوا ابْنَ عَوْفٍ فَصَلَّى بِهِمْ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى خَلْفَ ابْنِ عَوْفٍ مَا بَقِيَ مِنَ الصَّلَاةِ، فَلَمَّا سَلَّمَ ابْنُ عَوْفٍ قَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَضَى مَا سُبِقَ بِهِ. (ن)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): ഞാൻ നബി(സ)യിൽ നിന്ന് രണ്ടു കാര്യങ്ങൾക്കു സാക്ഷിയായശേഷം ആരോടും ചോദിച്ചിട്ടില്ല; നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ തിരുമേനി(സ) മലമൂത്ര വിസർജ്ജനത്തിൽ വ്യാപൃതനായി. ശേഷം വുദൂ ചെയ്തു. നബി(സ) തന്റെ മൂർദ്ധാവും തലപ്പാവിന്റെ ഇരു ഭാഗങ്ങളും തടവി. മുഗീറ പറയുന്നു: ജനങ്ങൾ അവരിലൊരാളുടെ പിന്നിൽ നിസ്കരിക്കുന്നതായി നബി(സ) കണ്ടു. നിസ്കാര സമയമായപ്പോൾ നബി(സ) അവരിലേക്കു ചെന്നില്ല. അതിനാലവർ ഇബ്നുഔഫിനു പിന്നിൽ നിസ്കരിച്ചു. അപ്പോൾ നബി(സ) വന്ന് (ജമാഅത്ത്) നിസ്കാരത്തിൽ നിന്ന് അവശേഷിക്കുന്ന അത്രയും (റക്അത്തുകൾ) ഇബ്നുഔഫിനു പിന്നിൽ നിന്ന് (ജമാഅത്തിൽ പങ്കെടുത്തുകൊണ്ട്) നിസ്കരിച്ചു. ഇബ്നുഔഫിന്റെ നിസ്കാരശേഷം നബി(സ) നഷ്ടപ്പെട്ട റക്അത്തുകൾ നിസ്കരിച്ചു. (ന)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَسَحَ أُذُنَيْهِ دَاخِلَهُمَا بِالسَّبَّابَتَيْنِ، وَخَالَفَ إِبْهَامَيْهِ إِلَى ظَاهِرِ أُذُنَيْهِ، فَمَسَحَ ظَاهِرَهُمَا وَبَاطِنَهُمَا. (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രണ്ടു ചെവികളുടെയും ഉൾഭാഗം ചൂണ്ടുവിരലുപയോഗിച്ച് തടവാറുണ്ടായിരുന്നു. രണ്ടു തള്ളവിരലുകളും ചെവിയുടെ പുറം ഭാഗത്തു കൊണ്ടുവരും. പിന്നെ ഉള്ളും പുറവും തടവും. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنِ الرُّبَيِّعِ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَسَحَ ظَاهِرَ أُذُنَيْهِ وَبَاطِنَهُمَا. وَفِي رِوَايَةٍ قَالَتْ: تَوَضَّأَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَدْخَلَ إِصْبَعَيْهِ فِي جُحْرَيْ أُذُنَيْهِ. (د,جه)', 'റുബയ്യിഅ്(റ): നബി(സ) വുദൂ ചെയ്തു, ചെവിയുടെ ഉള്ളും പുറവും തടവി. ഒരു റിപ്പോർട്ടിൽ: നബി(സ) വുദൂ ചെയ്തു, പിന്നെ രണ്ട് വിരലുകൾ ചെവിയുടെ ഉൾഭാഗത്തേക്ക് പ്രവേശിപ്പിക്കുകയും ചെയ്തു. (ദ,ജ)', 'الرُّبَيِّعِ', 'റുബയ്യിഅ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=11 and h.hadith_no=113), 1, 'وَفِي رِوَايَةٍ قَالَتْ: تَوَضَّأَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَدْخَلَ إِصْبَعَيْهِ فِي جُحْرَيْ أُذُنَيْهِ. (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِ يَكْرِبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرَهُمَا وَبَاطِنَهُمَا. (د,جه)', 'മിക്ദാമുബ്നുമഅ്ദീകരിബ(റ): നബി(സ) വുദൂ ചെയ്തു, തലയും ചെവിയുടെ ഉള്ളും പുറവും തടവി. (ദ,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِ يَكْرِبَ', 'മിക്ദാമുബ്നുമഅ്ദീകരിബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 177, 177, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عَبَّاسٍ قَالَ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَغَرَفَ غَرْفَةً فَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ وَجْهَهُ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُسْرَى، ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ: بَاطِنَهُمَا بِالسَّبَّاحَتَيْنِ وَظَاهِرَهُمَا بِإِبْهَامَيْهِ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُسْرَى. (ن)', 'ഇബ്നുഅബ്ബാസ് (റ): നബി (സ) വുദൂ ചെയ്തു. അപ്പോൾ ഒരു കൈക്കുമ്പിൾ വെള്ളം കൊണ്ട് വായിലും മൂക്കിലും വെള്ളം കൊണ്ടു. പിന്നീട് ഓരോ കുമ്പിൾ കൊണ്ട് മുഖം, വലതു കൈ, ഇടതു കൈ എന്നിവ കഴുകി. പിന്നെ തലയും, ചെവിയും തള്ള വിരലുകൾ കൊണ്ട് അകവും പുറവും തടവി. മറ്റൊരു കുമ്പിളുകൊണ്ട് വലതുകാലും ഇടതുകാലും കഴുകി. (ന)', 'ابْنِ عَبَّاسٍ قَالَ', 'ഇബ്നുഅബ്ബാസ് (റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي عَبْدِ اللهِ عَبْدِ الرَّحْمَنِ بْنِ عُسَيْلَةَ الصُّنَابِحِيِّ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " إِذَا تَوَضَّأَ الْعَبْدُ الْمُؤْمِنُ: فَتَمَضْمَضَ خَرَجَتِ الْخَطَايَا مِنْ فِيهِ، فَإِذَا اسْتَنْثَرَ خَرَجَتِ الْخَطَايَا مِنْ أَنْفِهِ، فَإِذَا غَسَلَ وَجْهَهُ خَرَجَتِ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَشْفَارِ عَيْنَيْهِ، فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتِ الْخَطَايَا مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ، فَإِذَا مَسَحَ بِرَأْسِهِ خَرَجَتِ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ، فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتِ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ، ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ نَافِلَةً لَهُ". (ن)', 'അബൂഅബ്ദില്ലാഹിബ്നു അബ്ദിർറഹ്മാൻ(റ): നബി (സ) പറഞ്ഞു: ഒരു വിശ്വാസി വുദൂ ചെയ്ത്, വായിൽ വെള്ളം കൊപ്ലിച്ചാൽ അതിലുള്ള പാപങ്ങൾ മായ്ക്കപ്പെടും. മൂക്കിൽ വെള്ളം കൊപ്ലിച്ചാൽ മൂക്കിൽ നിന്നുള്ള ദോഷങ്ങൾ മായ്ക്കപ്പെടും. മുഖം കഴുകിയാൽ മുഖത്തു നിന്നുള്ള ദോഷങ്ങൾ തന്റെ രണ്ടു കണ്ണുകളുടെ ഇമ മുളക്കുന്ന സ്ഥലത്തു നിന്നുവരെയുള്ളവ മായ്ക്കപ്പെടും. ഇരുകരങ്ങളും കഴുകിയാൽ അവയിൽ നിന്ന് തന്റെ നഖങ്ങളുടെ അടിഭാഗത്തുനിന്നുവരെ പാപങ്ങൾ മായ്ക്കപ്പെടും. തല തടവിയാൽ അതിൽ നിന്ന് ചെവികളിൽ നിന്നുവരെ ദോഷങ്ങൾ മായ്ക്കപ്പെടും. കാലുകൾ കഴുകിയാൽ അവയിൽ നിന്ന് തന്റെ നഖങ്ങളുടെ അടിഭാഗത്തുനിന്നു വരെ പാപങ്ങൾ മായ്ക്കപ്പെടും. പിന്നെ അവന്റെ പള്ളിയിലേക്കുള്ള സഞ്ചാരവും നിസ്കാരവുമെല്ലാം അവന് ഉത്തമമാണ്. (ന)', 'أَبِي عَبْدِ اللهِ عَبْدِ الرَّحْمَنِ بْنِ عُسَيْلَةَ الصُّنَابِحِيِّ', 'അബൂഅബ്ദില്ലാഹിബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْأُذُنَانِ مِنَ الرَّأْسِ". وَكَانَ يَمْسَحُ رَأْسَهُ مَرَّةً، وَكَانَ يَمْسَحُ الْمَأْقَيْنِ. (د,ت,جه)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "ചെവി രണ്ടും തലയിൽപെട്ടതാണ്." നബി(സ) തല ഒരു പ്രാവശ്യമേ തടവിയിരുന്നുള്ളൂ. അവടുന്ന് പീളക്കുഴി തടവാറുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْأُذُنَانِ مِنَ الرَّأْسِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ചെവി രണ്ടും തലയിൽപെട്ടതാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 178, 178, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَغَرَفَ غَرْفَةً فَمَضْمَضَ وَاسْتَنْشَقَ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ وَجْهَهُ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُسْرَى، ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ: بَاطِنَهُمَا بِالسَّبَّاحَتَيْنِ وَظَاهِرَهُمَا بِإِبْهَامَيْهِ، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُمْنَى، ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُسْرَى. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) വുദൂ ചെയ്തു. അപ്പോൾ ഒരു കൈക്കുമ്പിളിൽ വെള്ളംകൊണ്ട് വായിലും മൂക്കിലും വെള്ളംകൊണ്ടു. പിന്നീട് ഓരോ കുമ്പിൾ കൊണ്ട് മുഖം, വലതുകൈ, ഇടതുകൈ എന്നിവ കഴുകി. പിന്നെ തലയും, ചൂണ്ടുവിരലുകൾ കൊണ്ട് ചെവിയുടെ അകവും തള്ളവിരലുകൾ കൊണ്ട് പുറവും തടവി. മറ്റൊരു കുമ്പിൾ കൊണ്ട് വലതുകാലും വേറൊരു കുമ്പിൾ കൊണ്ട് ഇടതുകാലും കഴുകി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 178, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي عَبْدِ اللهِ عَبْدِ الرَّحْمَنِ بْنِ عُسَيْلَةَ الصُّنَابِحِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " إِذَا تَوَضَّأَ الْعَبْدُ الْمُؤْمِنُ: فَتَمَضْمَضَ خَرَجَتِ الْخَطَايَا مِنْ فِيهِ، فَإِذَا اسْتَنْثَرَ خَرَجَتِ الْخَطَايَا مِنْ أَنْفِهِ، فَإِذَا غَسَلَ وَجْهَهُ خَرَجَتِ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَشْفَارِ عَيْنَيْهِ، فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتِ الْخَطَايَا مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ، فَإِذَا مَسَحَ بِرَأْسِهِ خَرَجَتِ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ، فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتِ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ، ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ نَافِلَةً لَهُ". (ن)', 'അബൂഅബ്ദില്ലാഹിബ്നു അബ്ദിർറഹ്മാൻ(റ): നബി(സ) പറഞ്ഞു: "ഒരു വിശ്വാസി വുദൂ ചെയ്ത്, വായിൽ വെള്ളം കൊപ്ലിച്ചാൽ അതിലുള്ള പാപങ്ങൾ മായ്ക്കപ്പെടും. മൂക്കിൽ വെള്ളം കൊപ്ലിച്ചാൽ മൂക്കിൽ നിന്നുള്ള ദോഷങ്ങൾ മായ്ക്കപ്പെടും. മുഖം കഴുകിയാൽ മുഖത്തു നിന്നുള്ള ദോഷങ്ങൾ തന്റെ രണ്ടു കണ്ണുകളുടെ ഇമ മുളക്കുന്ന സ്ഥലത്തു നിന്നുവരെയുള്ളവ വരെ മായ്ക്കപ്പെടും. ഇരുകരങ്ങളും കഴുകിയാൽ അവയിൽ നിന്ന് നഖങ്ങളുടെ അടിഭാഗത്തു നിന്നുവരെ പാപങ്ങൾ മായ്ക്കപ്പെടും. തല തടവിയാൽ അതിൽ നിന്ന് ചെവികളിൽ നിന്നുവരെ ദോഷങ്ങൾ മായ്ക്കപ്പെടും. കാലുകൾ കഴുകിയാൽ അവയിൽ നിന്ന് നഖങ്ങളുടെ അടിഭാഗത്തു നിന്നുവരെ പാപങ്ങൾ മായ്ക്കപ്പെടും. പിന്നെ അവന്റെ പള്ളിയിലേക്കുള്ള സഞ്ചാരവും നിസ്കാരവുമെല്ലാം അവന് ഉത്തമമാണ്." (ന)', 'أَبِي عَبْدِ اللهِ عَبْدِ الرَّحْمَنِ بْنِ عُسَيْلَةَ الصُّنَابِحِيِّ', 'അബൂഅബ്ദില്ലാഹിബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ تَوَضَّأَ، فَغَسَلَ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ، ثُمَّ قَالَ: أَرَدْتُ أَنْ أُرِيَكُمْ طُهُورَ نَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'അലി(റ): വുദൂചെയ്ത് രണ്ടുകാലുകളും ഞെരിയാണി വരെ കഴുകിയതിനുശേഷം അദ്ദേഹം പറഞ്ഞു: നിങ്ങളുടെ നബി(സ) എങ്ങിനെയാണ് കഴുകിയതെന്ന് ഞാൻ നിങ്ങൾക്കു കാണിച്ചുതരാൻ ഉദ്ദേശിക്കുന്നു. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ الْمِقْدَامِ ابْنِ مَعْدِ يَكْرِبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا. (جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ): നബി(സ) വുദൂ ചെയ്തപ്പോൾ തന്റെ രണ്ടു പാദങ്ങളും മുമ്മൂന്നു പ്രാവശ്യം കഴുകാറുണ്ടായിരുന്നു. (ജ)', 'الْمِقْدَامِ ابْنِ مَعْدِ يَكْرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ الرُّبَيِّعِ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَانِي ابْنُ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمَا – فَسَأَلَنِي عَنْ هَذَا الْحَدِيثِ. تَعْنِي حَدِيثَهَا الَّذِي ذَكَرَتْ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، وَغَسَلَ رِجْلَيْهِ. فَقَالَ ابْنُ عَبَّاسٍ: إِنَّ النَّاسَ أَبَوْا إِلَّا الْغَسْلَ، وَلَا أَجِدُ فِي كِتَابِ اللهِ إِلَّا الْمَسْحَ. (جه)', 'റുബയ്യിഅ്(റ): ഇബ്നുഅബ്ബാസ്(റ) എന്റെയടുത്തു വന്ന് ഈ ഹദീസിനെ (നബി(സ) വുദൂ ചെയ്തപ്പോൾ രണ്ട് കാലുകളും കഴുകി.......)ക്കുറിച്ച് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ജനങ്ങൾ കഴുകലൊഴിച്ച് എല്ലാം ഒഴിവാക്കി. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ തടവലിനെയല്ലാതെ ഞാൻ കാണുന്നില്ല. (ജ)', 'الرُّبَيِّعِ', 'റുബയ്യിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 179, 179, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَيْلٌ لِلْعَقِبِ مِنَ النَّارِ". (ن)', 'അബൂഹുറൈറ(റ): അബുൽ ഖാസിം (നബി (സ)) പറഞ്ഞു: "ഞെരിയാണി കഴുകാത്തവർക്ക് നരകത്തിന്റെ നാശം." (ന)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 179, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُحِبُّ التَّيَامُنَ مَا اسْتَطَاعَ–فِي رِوَايَةٍ: فِي شَأْنِهِ كُلِّهِ– فِي طُهُورِهِ وَنَعْلِهِ وَتَرَجُّلِهِ. (ن)', 'ആഇശ(റ): നബി(സ) ചെരുപ്പു ധരിക്കുന്നതിലും, ശുദ്ധീകരണത്തിലും, മുടി ചീകുന്നതിലും - ഒരു റിപ്പോർട്ടിൽ: തന്റെ കാര്യങ്ങളിലെല്ലാം- സാധിക്കുന്നത്ര വലത്തേതിനു മുൻഗണന നൽകാൻ ഇഷ്ടപ്പെട്ടിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي حَيَّةَ الْوَادِعِيِّ قَالَ: رَأَيْتُ عَلِيًّا تَوَضَّأَ: فَغَسَلَ كَفَّيْهِ ثَلَاثًا، وَتَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا، وَغَسَلَ وَجْهَهُ ثَلَاثًا، وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، وَمَسَحَ بِرَأْسِهِ، وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا، ثُمَّ قَالَ: هَذَا وُضُوءُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അബൂഹയ്യതുൽ വാദിഈ(റ): അലി(റ) വുദൂ ചെയ്യുന്നതായി ഞാൻ കണ്ടു. രണ്ടു മുൻകൈകൾ മൂന്നു പ്രാവശ്യം കഴുകി. മൂക്കിലും വായിലും വെള്ളംകൊണ്ടു, മുഖം, മുഴംകൈകൾ എന്നിവ മുമ്മൂന്നു തവണ കഴുകി, തല തടവി, ഇരുകാലുകളും മുമ്മൂന്നു തവണ കഴുകി. പിന്നെ പറഞ്ഞു: ഇതാണ് നബി(സ)യുടെ വുദൂ. (ന)', 'أَبِي حَيَّةَ الْوَادِعِيِّ قَالَ', 'അബൂഹയ്യതുൽ വാദിഈ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنِ الْقَيْسِيِّ: أَنَّهُ كَانَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأُتِيَ بِمَاءٍ فَقَالَ عَلَى يَدَيْهِ مِنَ الْإِنَاءِ فَغَسَلَهُمَا مَرَّةً، وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ مَرَّةً مَرَّةً، وَغَسَلَ رِجْلَيْهِ بِيَمِينِهِ كِلْتَاهُمَا. (ن)', 'ഖൈസിയ്യ്(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ വെള്ളം കൊണ്ടുവരപ്പെട്ടു. കൈയിൽ വെള്ളമൊഴിക്കാനാവശ്യപ്പെട്ടു. ശേഷം കൈകൾ കഴുകി. മുഖവും മുഴംകൈകളും ഓരോ പ്രാവശ്യം കഴുകി. പിന്നെ രണ്ട് കാലുകളും വലംകൈ കൊണ്ട് കഴുകി. (ന)', 'الْقَيْسِيِّ', 'ഖൈസിയ്യ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ". (م,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "മടമ്പുകൾക്ക് (മടമ്പു കഴുകാതെ വുദൂ ചെയ്യുന്നവന്) നരകശിക്ഷയാൽ നാശം." (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَيْلٌ لِلْعَقِبِ مِنَ النَّارِ". (ن)', 'അബൂഹുറൈറ(റ): അബുൽഖാസിം - പ്രവാചകൻ - (സ) പറഞ്ഞു: "മടമ്പുകൾക്ക് (ഞെരിയാണി കഴുകാത്തവർക്ക്) നരകത്തിലെ ശിക്ഷയാൽ നാശം." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 180, 180, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أبي سَلَمَةَ رَضِيَ اللهُ عَنْها قَالَ: رَأَتْ عَائشةُ – رَضِيَ اللهُ عَنْها – عَبْدَ الرَّحْمَنِ وَهُوَ يَتَوَضَّأُ، فَقالَتْ: أَسْبِغِ الْوُضُوءَ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "وَيْلٌ لِلْعَراقِيبِ مِنَ النَّارِ". (م,جه)', 'അബൂസലമ(റ): അബ്ദുർറഹ്മാൻ വുദൂ ചെയ്യുന്നത് ആഇശ(റ) കണ്ടപ്പോൾ അവർ പറഞ്ഞു: നന്നായി വുദൂ ചെയ്യുക, നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: " മടമ്പുകളിലെ ഞരമ്പുകൾക്ക് (മടമ്പ് ശ്രദ്ധിക്കാത്തവന്ന്) നരകത്തിലെ ശിക്ഷയാൽ നാശമുണ്ട്." (മു,ജ)', 'أبي سَلَمَةَ', 'അബൂസലമ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ جابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "وَيْلٌ لِلْعَراقِيبِ مِنَ النَّارِ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: " മടമ്പുകളിലെ ഞരമ്പുകൾക്ക് (മടമ്പുകാൽ സൂക്ഷിച്ചു കഴുകാത്തവന്) നരകത്തിലെ ശിക്ഷയാൽ നാശമുണ്ട്." (ജ)', 'جابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ خالدِ بْنِ الْوَلِيدِ، وَيَزِيدَ بْنِ أبي سُفْيَانَ، وَشُرَحْبِيلَ ابْنِ حَسَنَةَ، وَعَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُم: كُلُّ هَؤُلَاءِ سمِعُوا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتِمُّوا الْوُضُوءَ، وَيْلٌ لِلأَعْقابِ مِنَ النَّارِ". (جه)', 'ഖാലിദ്ബ്നുൽ വലീദ്, യസീദുബ്നു അബൂസുഫ്യാൻ, ശുറഹ്ബീലുബ്നു ഹസന, അംറുബ്നുൽ ആസ്(റ) ഇവർ നബി(സ) പറയുന്നതായി കേട്ടു: "നിങ്ങൾ അന്യൂനമായ രീതിയിൽ വുദൂ ചെയ്യുക. കാരണം, മടമ്പുകൾക്ക് (മടമ്പു കഴുകാതെ വുദൂ ചെയ്യുന്നവന്) നരകശിക്ഷയാൽ നാശം.." (ജ)', 'خالدِ بْنِ الْوَلِيدِ، وَيَزِيدَ بْنِ أبي سُفْيَانَ، وَشُرَحْبِيلَ ابْنِ حَسَنَةَ، وَعَمْرِو بْنِ الْعَاصِ', 'ഖാലിദ്ബ്നുൽ വലീദ്, യസീദുബ്നു അബൂസുഫ്യാൻ, ശുറഹ്ബീലുബ്നു ഹസന, അംറുബ്നുൽ ആസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ هَمَّامِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: بَالَ جَرِيرُ بْنُ عَبْدِ اللهِ، ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ، فَقِيلَ لَهُ: أَتَفْعَلُ هَذَا؟ قَالَ: وَمَا يَمْنَعُنِي وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ؟. قَالَ إِبْرَاهِيمُ: كَانَ يُعْجِبُهُمْ حَدِيثُ جَرِيرٍ، لأَنَّ إِسْلَامَهُ كَانَ بَعْدَ نُزُولِ الْمَائِدَةِ. (ق,د,ن,جه)', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ): ആദ്ദേഹം പറഞ്ഞു: ഒരിക്കൽ ജരീറുബ്നു അബ്ദില്ല മൂത്രമൊഴിച്ചു, ശേഷം വുദൂ ചെയ്ത് കാലുറ തടവി, അപ്പോൾ അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: താങ്കളിപ്രകാരം ചെയ്യുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിരിക്കെ എന്നെ എന്തിനാണ് നിങ്ങൾ വിലക്കുന്നത്. ഇബ്രാഹീം പറഞ്ഞു: ജരീറി(റ)ന്റെ സംഭവം അവരെ അത്ഭുതപ്പെടുത്തിയിരുന്നു. കാരണം, സൂറത്തുൽമാഇദ ഇറങ്ങിയ ശേഷമാണദ്ദേഹം മുസ്ലിമായത്. (ബു,മു,ദ,ന,ജ)', 'هَمَّامِ بْنِ الْحَارِثِ', 'ഹമ്മാമുബ്നുൽ ഹാരിസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، وَمَسَحَ عَلَى خُفَّيْهِ. (جه)', 'ഹുദൈഫ(റ): നബി(സ) വുദൂ ചെയ്തു തന്റെ ഖുഫ്ഫകൾ തടവുകയും ചെയ്തു. (ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ خَرَجَ لِحَاجَتِهِ، فَاتَّبَعَهُ الْمُغِيرَةُ بِإِدَاوَةٍ فِيهَا مَاءٌ، حَتَّى فَرَغَ مِنْ حَاجَتِهِ فَتَوَضَّأَ، وَمَسَحَ عَلَى الْخُفَّيْنِ. (ق,د,ن,جه)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): അദ്ദേഹം നബി(സ)യിൽ നിന്ന്: നബി(സ) ആവശ്യ പൂർത്തീകരണ (മലമൂത്ര വിസർജ്ജന)ത്തിനായി പുറപ്പെട്ടു. അപ്പോൾ ഒരു വെള്ളപ്പാത്രവുമായി മുഗീറ നബി(സ)യെ പിന്തുടർന്നു. ആവശ്യം നിർവ്വഹിച്ച ശേഷം നബി(സ) വുദൂ ചെയ്യുകയും ഖുഫ്ഫ തടവുകയും ചെയ്തു. (ബു,മു,ദ,ന,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 181, 181, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ، فَقِيلَ لَهُ: أَتَمْسَحُ؟ فَقَالَ: قَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ. وَكَانَ أَصْحَابُ عَبْدِ اللهِ يُعْجِبُهُمْ قَوْلُ جَرِيرٍ، وَكَانَ إِسْلَامُ جَرِيرٍ قَبْلَ مَوْتِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَسِيرٍ. (ن)', 'ജരീറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹം വുദൂ ചെയ്ത് തന്റെ ഖുഫ്ഫകൾ തടവി. അപ്പോൾ ചോദിക്കപ്പെട്ടു: നിങ്ങളിങ്ങനെ തടവുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം തടവുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. അബ്ദുല്ലയുടെ കൂട്ടുകാരെ ജരീറിന്റെ വാക്കുകൾ അത്ഭുതപ്പെടുത്തിയിരുന്നു. അദ്ദേഹത്തിന്റെ ഇസ്ലാമാശ്ലേഷണം നബി(സ)യുടെ മരണത്തിനു അൽപം മുമ്പായിരുന്നു. (ന)', 'جَرِيرِ بْنِ عَبْدِ اللهِ', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 181, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ. (ن)', 'അംറുബ്നു ഉമയ്യ(റ): അദ്ദേഹം നബി(സ) വുദൂ ചെയ്യുമ്പോൾ ഖുഫ്ഫകളിൽ തടവിയതായി കണ്ടു. (ന)', 'عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ', 'അംറുബ്നു ഉമയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبِلَالٌ الأَسْوَاقَ، فَذَهَبَ لِحَاجَتِهِ ثُمَّ خَرَجَ، قَالَ أُسَامَةُ: فَسَأَلْتُ بِلالًا – رَضِيَ اللهُ عَنْهُ – مَا صَنَعَ؟ فَقَالَ بِلَالٌ: ذَهَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ، ثُمَّ تَوَضَّأَ: فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، وَمَسَحَ بِرَأْسِهِ، وَمَسَحَ عَلَى الْخُفَّيْنِ، ثُمَّ صَلَّى. (ن)', 'ഉസാമതുബ്നു സൈദ്(റ): റസൂലും(സ) ബിലാലും(റ) അങ്ങാടികളിൽ പോയി. അപ്പോൾ നബി(സ) മലമൂത്ര വിസർജ്ജനത്തിനു ശേഷം മടങ്ങി വന്നു. ഉസാമ(റ) പറയുന്നു: ഞാൻ ബിലാലി(റ)നോട് ചോദിച്ചു: നബി(സ) എന്താണ് ചെയ്തത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) തന്റെ ആവശ്യം നിർവ്വഹിക്കാൻ പോയി. പിന്നെ വുദൂ ചെയ്തു. അപ്പോളവിടുന്ന് ഇരുകൈകളും മുഖവും കഴുകുകയും തല തടവുകയും കാലുറ തടവുകയും ചെയ്തു. പിന്നെ നിസ്കരിച്ചു. (ന)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَأَى سَعْدَ بْنَ مَالِكٍ رَضِيَ اللهُ عَنْهُ وَهُوَ يَمْسَحُ عَلَى الْخُفَّيْنِ، فَقَالَ: إِنَّكُمْ لَتَفْعَلُونَ ذَلِكَ؟ فَاجْتَمَعْنَا عِنْدَ عُمَرَ، فَقَالَ سَعْدٌ لِعُمَرَ: أَفْتِ ابْنَ أَخِي فِي الْمَسْحِ عَلَى الْخُفَّيْنِ. فَقَالَ عُمَرُ: كُنَّا وَنَحْنُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَمْسَحُ عَلَى خِفَافِنَا، لَا نَرَى بِذَلِكَ بَأْسًا، فَقَالَ ابْنُ عُمَرَ: وَإِنْ جَاءَ مِنَ الْغَائِطِ؟ قَالَ: نَعَمْ. [ز: في إسناده مدلس عنعنه] (جه)', 'ഇബ്നുഉമർ(റ): സഅ്ദുബ്നു മാലിക്(റ) ഖുഫ്ഫ തടവുന്നത് അദ്ദേഹം കണ്ടു. അദ്ദേഹം ചോദിച്ചു: നിങ്ങളെന്താണു ചെയ്യുന്നത്? അങ്ങനെ ഞങ്ങൾ ഉമറി(റ)ന്റടുത്തു ചെന്നു. ഉമറി(റ)നോടു സഅ്ദ് പറഞ്ഞു: സഹോദരപുത്രാ, ഖുഫ്ഫ തടവുന്നതിൽ മതവിധി നൽകിയാലും!. ഉമർ(റ) പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഖുഫ്ഫ തടവാറുണ്ടായിരുന്നു. അതിൽ ഒരു കുഴപ്പവും കാണുന്നില്ല. ഇബ്നുഉമർ(റ) ചോദിച്ചു: മലമൂത്ര വിസർജ്ജന ശേഷവും? ഉമർ(റ) പറഞ്ഞു: അതെ. (ഇതിന്റെ പരമ്പരയിൽ ഇതിനെ അൻ അനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ سَهْلٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَسَحَ عَلَى الْخُفَّيْنِ، وَأَمَرَنَا بِالْمَسْحِ عَلَى الْخُفَّيْنِ. [ز: في إسناده ضعيف] (جه)', 'സഹ്ലുസ്സാഇദീ(റ): നബി(സ) ഖുഫ്ഫ തടവുകയും തടവാൻ ഞങ്ങളോട് കൽപിക്കുകയും ചെയ്തു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'سَهْلٍ السَّاعِدِيِّ', 'സഹ്ലുസ്സാഇദീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَقَالَ: "هَلْ مِنْ مَاءٍ". فَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ، ثُمَّ لَحِقَ بِالْجَيْشِ فَأَمَّهُمْ. [ز: في إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ നബി(സ) ചോദിച്ചു: "വെള്ളമുണ്ടോ?" അപ്പോൾ വുദൂ ചെയ്യുകയും ഖുഫ്ഫ തടവുകയും ചെയ്തു. പിന്നെ സൈന്യത്തോടൊപ്പം ചേർന്ന് അവർക്ക് നിസ്കാരത്തിന് നേതൃത്വം നൽകി. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 182, 182, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّجَاشِيَّ أَهْدَى لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خُفَّيْنِ أَسْوَدَيْنِ سَاذَجَيْنِ، فَلَبِسَهُمَا، ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَيْهِمَا. (د,ت,جه)', 'ബുറൈദ(റ): നജ്ജാശി രാജാവ് നബി(സ)ക്ക് നല്ല കറുത്ത ഖുഫ്ഫ സമ്മാനിച്ചു. നബി(സ) അതു ധരിച്ച് വുളൂ ചെയ്യുകയും, അവ തടവുകയും ചെയ്തു. (ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 183, 183, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ جَابِرٍ قَالَ رَضِيَ اللهُ عَنْهُ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ يَتَوَضَّأُ وَيَغْسِلُ خُفَّيْهِ، فَقَالَ بِيَدِهِ، كَأَنَّهُ دَفَعَهُ: "إِنَّمَا أُمِرْتَ بِالْمَسْحِ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ: "هَكَذَا مِنْ أَطْرَافِ الأَصَابِعِ إِلَى أَصْلِ السَّاقِ، وَخَطَّطَ بِالأَصَابِعِ. (جه)', 'ജാബിർ(റ): വുദൂ ചെയ്യുകയും ഖുഫ്ഫ തടവുകയും ചെയ്യുന്ന ഒരാൾക്കരികിലൂടെ നബി(സ) കടന്നു പോയപ്പോൾ അയാളുടെ ചെയ്തിയെ തടയുന്ന വിധത്തിൽ കൈ കൊണ്ട് ആംഗ്യം കാണിച്ച് അവിടുന്ന് പറഞ്ഞു: "തടവാനേ നീ കൽപിക്കപ്പെട്ടിട്ടുള്ളൂ" (തന്റെ കൈ കൊണ്ട് ആംഗ്യം കാണിച്ചു കൊണ്ട്) പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇങ്ങനെ വിരലിന്റെ അറ്റത്തുനിന്ന് തുടങ്ങി കണങ്കാലിന്റെ അകം വരെ" - പ്രവാചകൻ(സ) തന്റെ വിരലുകൾ കൊണ്ട് നേരെ വരച്ചു (തടവി) കാണിച്ചു. (ജ)', 'جَابِرٍ قَالَ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 183, 183, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَدِمَ عَلَى عُمَرَ بْنِ الْخَطَّابِ مِنْ مِصْرَ، فَقَالَ: مُنْذُ كَمْ لَمْ تَنْزِعْ خُفَّيْكَ؟ قَالَ: مِنَ الْجُمُعَةِ إِلَى الْجُمُعَةِ. قَالَ: أَصَبْتَ السُّنَّةَ. (جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): അദ്ദേഹം മിസ്റിൽ നിന്നും ഉമറി(റ)ന്റെ അടുത്തെത്തി. അദ്ദേഹം ചോദിച്ചു: എത്ര കാലമായി നിങ്ങൾ ഖുഫ്ഫ ധരിച്ചിട്ട്? ഉഖ്ബ പറഞ്ഞു: കഴിഞ്ഞ വെള്ളിയാഴ്ച മുതൽ ഈ വെള്ളിയാഴ്ച വരെ. ഉമർ(റ) പറഞ്ഞു: താങ്കൾ നബിചര്യ എടുത്തിരിക്കുന്നു. (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 183, 183, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أُبَيِّ بْنِ عِمَارَةَ رَضِيَ اللهُ عَنْهُ – وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ صَلَّى فِي بَيْتِهِ الْقِبْلَتَيْنِ كِلْتَيْهِمَا – أَنَّهُ قَالَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَمْسَحُ عَلَى الْخُفَّيْنِ؟ قَالَ: "نَعَمْ". قَالَ: يَوْمًا، قَالَ: "وَيَوْمَيْنِ" قَالَ: وَثَلَاثًا؟ حَتَّى بَلَغَ سَبْعًا، قَالَ: "لَهُ وَمَا بَدَا لَكَ". [ قَالَ النَّوَوِي فِي شَرْحِ مُسْلِمٍ: هُوَ حَدِيثٌ ضَعِيفٌ بِاتِّفَاقِ الْمُحَدِّثِينَ] (د,جه)', 'ഉബയ്യുബ്നു അമ്മാറ(റ): നബി(സ) അദ്ദേഹത്തിന്റെ വീട്ടിൽ വെച്ച് രണ്ട് ഖിബ്ലയിലേക്കും തിരിഞ്ഞ് നിസ്കരിച്ചിരുന്നു. അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു; ഞാൻ രണ്ട് ഖുഫ്ഫയുടെ മേലും തടവട്ടെയോ? നബി(സ) പറഞ്ഞു: ''അതെ.'' അദ്ദേഹം ചോദിച്ചു: രണ്ടു ദിവസം? നബി(സ) പറഞ്ഞു: ''അതെ.'' അദ്ദേഹം: മൂന്നു ദിവസം? നബി(സ): ''അതെ.'' അങ്ങനെ ഏഴു ദിവസം വരെയെത്തി. അപ്പോൾ നബി(സ) പറഞ്ഞു: ''അതും അതിനപ്പുറവും നിനക്ക് അനുവദനീയമാണ്.'' (ഹദീസ് പണ്ധിതരുടെ ഏകോപിച്ച അഭിപ്രായപ്രകാരം ഈ ഹദീസ് ദുർബ്വലാണെന്ന് ഇമാം നവവി തന്റെ ''ശറഹ് മുസ്ലിമിൽ'' പറഞ്ഞിട്ടുണ്ട്) (ദ,ജ)', 'أُبَيِّ بْنِ عِمَارَةَ', 'ഉബയ്യുബ്നു അമ്മാറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], 'قَالَ النَّوَوِي فِي شَرْحِ مُسْلِمٍ: هُوَ حَدِيثٌ ضَعِيفٌ بِاتِّفَاقِ الْمُحَدِّثِينَ', null, 183, 183, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ خُزَيْمَةَ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْمُسَافِرِ ثَلَاثًا، وَلَوْ مَضَى السَّائِلُ عَلَى مَسْأَلَتِهِ لَجَعَلَهَا خَمْسًا. وفي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهُنَّ لِلْمُسَافِرِ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ". (د,ت,جه)', 'ഖുസൈമതുബ്നു സാബിത്(റ): നബി(സ) യാത്രക്കാരന് (ഖുഫ്ഫ തടവൽ അനുവദനീയമായ സമയ പരിധി) മൂന്നു ദിവസമാക്കിക്കൊടുത്തു, ചോദ്യകർത്താവ് ആവശ്യം തുടർന്നിരുന്നെങ്കിൽ നബി(സ) അത് അഞ്ചാക്കുമായിരുന്നു. ഒരു റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: യാത്രക്കാരന് മൂന്നു പകലും രാത്രികളുമാണ് ഖുഫ്ഫ തടവാൻ അനുവദിക്കപ്പെട്ടിട്ടുള്ളത്. (ദ,തു,ജ)', 'خُزَيْمَةَ بْنِ ثَابِتٍ', 'ഖുസൈമതുബ്നു സാബിത്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 184, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=11 and h.hadith_no=146), 1, 'وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهُنَّ لِلْمُسَافِرِ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ". (د,ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالُوا يَا رَسُولَ اللهِ، مَا الطُّهُورُ عَلَى الْخُفَّيْنِ؟ قَالَ: "لِلْمُسَافِرِ ثَلَاثَةُ أَيَّامٍ وَلَيَالِيهِنَّ، وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ". (جه)', 'അബൂഹുറൈറ(റ): അനുചരന്മാർ ചോദിച്ചു: നബിയേ, ഖുഫ്ഫയുടെ മേലുള്ള ശുദ്ധികാലം (തടവാൻ പറ്റുന്ന കാലയളവ്) എത്രയാണ്? നബി(സ) പറഞ്ഞു: "യാത്രക്കാരന് മൂന്നുപകലും മൂന്നു രാത്രികളും, നാട്ടിൽ താമസിക്കുന്നവന് ഒരു പകലും ഒരു രാത്രിയും." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 184, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَقَالَ تَخَلَّفْ يَا مُغِيرَةُ، وَامْضُوا أَيُّهَا النَّاسُ". فَتَخَلَّفْتُ وَمَعِي إِدَاوَةٌ مِنْ مَاءٍ، وَمَضَى النَّاسُ، فَذَهَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ، فَلَمَّا رَجَعَ ذَهَبْتُ أَصُبُّ عَلَيْهِ، وَعَلَيْهِ جُبَّةٌ رُومِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ، فَأَرَادَ أَنْ يُخْرِجَ يَدَهُ مِنْهَا فَضَاقَتْ عَلَيْهِ، فَأَخْرَجَ يَدَهُ مِنْ تَحْتِ الْجُبَّةِ، فَغَسَلَ وَجْهَهُ وَيَدَيْهِ، وَمَسَحَ بِرَأْسِهِ، وَمَسَحَ عَلَى خُفَّيْهِ. (ن)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരുന്നു. നബി(സ) പറഞ്ഞു: "മുഗീറാ, പിന്നോട്ടു നിൽക്ക്. ജനങ്ങളേ നിങ്ങൾ നടക്കുവിൻ." ഞാൻ പിന്നോട്ടു നിന്നു. എന്റെ അടുത്ത് ഒരു ചെറിയ വെള്ളപ്പാത്രമുണ്ടായിരുന്നു. നബി(സ) മലമൂത്ര വിസർജ്ജനത്തിനായി പോയി. മടങ്ങിവന്നപ്പോൾ ഞാൻ വെള്ളമൊഴിച്ചു കൊടുത്തു. തിരുമേനി(സ) കൈകൾ ഇടുങ്ങിയ ഒരു റോമൻ നിർമ്മിത ജുബ്ബയായിരുന്നു ധരിച്ചിരുന്നത്. കൈ പുറത്തെടുക്കാൻ തുനിഞ്ഞപ്പോൾ നബി(സ)ക്ക് പ്രയാസമനുഭവപ്പെട്ടു. അപ്പോൾ തന്റെ കൈ ജുബ്ബയുടെ കീഴ്ഭാഗത്തു കൂടി പുറത്തെടുക്കുകയും കൈയും മുഖവും കഴുകി, തലയും ഖുഫ്ഫകളും തടവുകയും ചെയ്തു. (ന)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 184, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ رَخَّصَ لِلْمُسَافِرِ – إِذَا تَوَضَّأَ وَلَبِسَ خُفَّيْهِ ثُمَّ أَحْدَثَ وُضُوءًا – أَنْ يَمْسَحَ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ، وَلِلْمُقِيمِ يَوْمًا وَلَيْلَةً. (جه)', 'അബൂബക്കർ(റ): നബി(സ)യിൽ നിന്ന്: നബി(സ) യാത്രക്കാരന് ഇളവു നൽകി - വുദൂ ചെയ്ത് ഖുഫ്ഫ ധരിച്ചശേഷം വുദൂ മുറിഞ്ഞാൽ -അവന് മൂന്നു പകലും രാത്രികളും ഖുഫ്ഫക്കുമേൽ തടവാം. നാട്ടിൽ താമസിക്കുന്നവന് ഒരു പകലും ഒരു രാത്രിയും. (ജ)', 'أَبِي بَكْرَةَ', 'അബൂബക്കർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 184, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: جَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْمُسَافِرِ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهُنَّ، وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ. يَعْنِي فِي الْمَسْحِ. (ن)', 'അലി(റ): നബി(സ) ഖുഫ്ഫ തടവുന്നതിൽ യാത്രക്കാരന് മൂന്നു ദിനരാത്രങ്ങളും നാട്ടിൽ താമസിക്കുന്നവന്ന് ഒരു രാവും പകലും നിശ്ചയിച്ചു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 184, 184, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ زِرِّ بْنِ جَيْشٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ صَفْوَانَ بْنَ عَسَّالٍ عَنِ الْمَسْحِ عَلَى الْخُفَّيْنِ؟ فَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُنَا إِذَا كُنَّا مُسَافِرِينَ: أَنْ نَمْسَحَ عَلَى خِفَافِنَا وَلَا نَنْزِعَهَا ثَلَاثَةَ أَيَّامٍ، مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ، إِلَّا مِنْ جَنَابَةٍ. (ن)', 'സിർറുബ്നു ജൈശ്(റ): ഞാൻ സ്വഫ്വാനുബ്നു അസ്സാലിനോട് ഖുഫ്ഫ തടവുന്നതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: യാത്രക്കാരായിരിക്കെ ഖുഫ്ഫ തടവാനും വലിയ അശുദ്ധി ഉണ്ടായാൽ ഒഴികെ മലമൂത്ര വിസർജ്ജനം ചെയ്തതിനാലോ, ഉറങ്ങിയത് കാരണത്താലോ (വുദൂ മുറിഞ്ഞാൽ) അവ അഴിക്കാതിരിക്കാനും നബി(സ) ഞങ്ങളോട് കൽപിച്ചിരുന്നു. (ന)', 'زِرِّ بْنِ جَيْشٍ', 'സിർറുബ്നു ജൈശ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 184, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ. [ضعيف] (جه)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) വുദൂ ചെയ്യുകയും രണ്ട് ചെരുപ്പും കാലുറയും തടവുകയും ചെയ്തു. (ഹദീസ് ദുർബ്വലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي مُوسَى الأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ضعيف', null, 185, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي حَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عَلِيًّا رَضِيَ اللهُ عَنْهُ تَوَضَّأَ ثَلَاثًا ثَلَاثًا، ثُمَّ قَامَ فَشَرِبَ فَضْلَ وَضُوئِهِ، وَقَالَ: صَنَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَمَا صَنَعْتُ. (ن)', 'അബൂഹയ്യ(റ): അലി(റ) മുമ്മൂന്നു തവണയായി വുദൂ ചെയ്യുന്നത് ഞാൻ കണ്ടു. പിന്നെ അദ്ദേഹം എഴുന്നേറ്റ് ബാക്കിവന്ന വെള്ളം കുടിച്ചു. ശേഷം പറഞ്ഞു: ഞാൻ ഈ ചെയ്തതുപോലെ നബി(സ) ചെയ്തിട്ടുണ്ട്. (ന)', 'أَبِي حَيَّةَ', 'അബൂഹയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 185, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْبَطْحَاءِ، وَأَخْرَجَ بِلَالٌ رَضِيَ اللهُ عَنْهُ فَضْلَ وَضُوئِهِ، فَابْتَدَرَهُ النَّاسُ، فَنِلْتُ مِنْهُ شَيْئًا، وَرَكَزْتُ لَهُ الْعَنَزَةَ فَصَلَّى بِالنَّاسِ، وَالْحُمُرُ وَالْكِلَابُ وَالْمَرْأَةُ يَمُرُّونَ بَيْنَ يَدَيْهِ. (ن)', 'അബൂജുഹൈഫ(റ): മരുഭൂമിയിൽ വെച്ച് ഞാൻ നബി(സ)യുമായി സന്ധിച്ചു. അപ്പോൾ ബിലാൽ(റ) നബി(സ)യുടെ വുദൂവിന്റെ ബാക്കി വെള്ളവുമായി പുറത്തുവന്നു. ജനങ്ങൾ അതിന്നായി കുതിച്ചെത്തി. അതിൽ നിന്നല്പം എനിക്കും കിട്ടി. ഞാൻ നബി(സ)ക്കായി എന്റെ ചെറിയ കുന്തം നിലത്തു കുത്തി നിർത്തി. നബി(സ) ജനങ്ങളെയുമായി നിസ്കരിച്ചു. അപ്പോൾ അതിനു മുന്നിലൂടെ കഴുതകളും നായകളും സ്ത്രീകളും നടക്കുന്നുണ്ടായിരുന്നു. (ന)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 185, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضْتُ، فَأَتَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ يَعُودَانِي، فَوَجَدَانِي قَدْ أُغْمِيَ عَلَيَّ، فَتَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَصَبَّ عَلَيَّ وَضُوءَهُ. (ق,ت,ن,جه)', 'ജാബിർ(റ): ഞാൻ രോഗിയായിരിക്കെ നബി(സ)യും അബൂബക്കറും(റ) എന്നെ സന്ദർശിക്കാൻ വന്നു. ഞാൻ ബോധരഹിതനായത് അവർ കണ്ടു. പിന്നെ നബി(സ) വുദൂ ചെയ്തു. അവശേഷിച്ച വെള്ളം എന്റെ മേൽ ഒഴിച്ചു. (ബു,മു,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 185, 185, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ عَلَيْنَا رِعَايَةُ الإِبِلِ، فَجَاءَتْ نَوْبَتِي فَرَوَّحْتُهَا بِعَشِيٍّ، فَأَدْرَكْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَائِمًا يُحَدِّثُ النَّاسَ، فَأَدْرَكْتُ مِنْ قَوْلِهِ: "مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ، فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ، إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ". قَالَ: فَقُلْتُ مَا أَجْوَدَ هَذِهِ، فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ يَقُولُ: الَّتِي قَبْلَهَا أَجْوَدُ، فَنَظَرْتُ فَإِذَا عُمَرُ قَالَ: إِنِّي قَدْ رَأَيْتُكَ جِئْتَ آنِفًا، قَالَ: "مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُبْلِغُ – أَوْ فَيُسْبِغُ – الْوَضُوءَ، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا عَبْدُ اللهِ وَرَسُولُهُ، إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ، يَدْخُلُ مِنْ أَيِّهَا شَاءَ". (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞങ്ങൾക്ക് ഒട്ടകത്തെ മേയ്ക്കാനുണ്ടായിരുന്നു. എന്റെ ഊഴമായപ്പോൾ രാത്രി ഭക്ഷണവുമായി ഞാൻ പോയി. അപ്പോൾ നബി(സ) നിന്നുകൊണ്ട് ജനങ്ങളോട് സംസാരിക്കുന്നത് ഞാൻ കണ്ടു. ഞാൻ നബിയുടെ സംസാരം കേട്ടു: "വുദൂ ചെയ്യുകയും വുളുവിനെ നന്നാക്കുകയും, പിന്നെ ഹൃദയവും മുഖവുമായി മുന്നിട്ട് രണ്ട് റക്അത്ത് (ആത്മാർത്ഥമായി) നിസ്കരിക്കുകയും ചെയ്ത എല്ലാ മുസ്ലിമിനും സ്വർഗ്ഗം നിർബന്ധമായിരിക്കുന്നു." അദ്ദേഹം പറഞ്ഞു: ഞാൻ പറഞ്ഞു: എത്ര മഹത്തരം! അപ്പോൾ മുമ്പിൽ നിന്നൊരാൾ പറഞ്ഞു: ഇതിനു മുമ്പുള്ളത് കൂടുതൽ മഹത്തരം. ഞാൻ തിരിഞ്ഞു നോക്കിയപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നീ അല്പം മുമ്പ് വന്നത് ഞാൻ കണ്ടു. അദ്ദേഹം (നബി) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ (നന്നായി) വുദൂ ചെയ്യുകയും, ശേഷം ''അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും, മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു'' എന്നു പറയുകയും ചെയ്താൽ അവന് സ്വർഗ്ഗത്തിന്റെ എട്ടു കവാടങ്ങളും തുറക്കപ്പെടും. അവയിൽ നിന്ന് അവനുദ്ദേശിച്ചതിലൂടെ അവന് പ്രവേശിക്കാം." (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 185, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ الْحَكَمِ بْنِ سُفْيَانَ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأً، ثُمَّ أَخَذَ كَفًّا مِنْ مَاءٍ فَنَضَحَ بِهِ فَرْجَهُ. (د,ن,جه)', 'ഹകമുബ്നു സുഫ്യാനുസ്സഖഫി(റ): നബി(സ) വുദൂ ചെയ്യുന്നത് അദ്ദേഹം കണ്ടു. വുദൂവിനു ശേഷം അല്പം വെള്ളമെടുത്ത് നബി(സ) തന്റെ ഗുഹ്യസ്ഥാനത്ത് കുടഞ്ഞു. (ദ,ന,ജ)', 'الْحَكَمِ بْنِ سُفْيَانَ الثَّقَفِيِّ', 'ഹകമുബ്നു സുഫ്യാനുസ്സഖഫി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أُسَامَةَ بْنِ زَيْدِ بْنِ حَارِثَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَّمَنِي جِبْرَائِيلُ الْوُضُوءَ، وَأَمَرَنِي أَنْ أَنْضَحَ تَحْتَ ثَوْبِي، لِمَا يَخْرُجُ مِنَ الْبَوْلِ بَعْدَ الْوُضُوءِ". [ز: في إسناده ضعيف] (جه)', 'ഉസാമതുബ്നു സൈദുബ്നി ഹാരിസ(റ): നബി(സ) പറഞ്ഞു: "ജിബ്രീൽ(അ) എന്നെ വുദൂ ചെയ്യാൻ പഠിപ്പിച്ചു, എന്റെ വസ്ത്രത്തിനുള്ളിൽ (വെള്ളം) കുടയാൻ എന്നോട് കൽപിക്കുകയും ചെയ്തു. വുദൂവിനുശേഷം മൂത്രത്തിന്റെ അംശങ്ങൾ പുറത്തുവരുന്നതിനാലാണിങ്ങനെ ചെയ്യാൻ കൽപ്പിച്ചിരുന്നത്". [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'أُسَامَةَ بْنِ زَيْدِ بْنِ حَارِثَةَ', 'ഉസാമതുബ്നു സൈദുബ്നി ഹാരിസ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَوَضَّأْتَ فَانْتَضِحْ". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നീ വുദൂ ചെയ്യുമ്പോൾ (അല്പം വെള്ളം ശരീരത്തിൽ) കുടയുക." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَضَحَ فَرْجَهُ. [ز: في إسناده ضعيف] (جه)', 'ജാബിർ(റ): നബി(സ) വുദൂ ചെയ്തപ്പോൾ തന്റെ ഗുഹ്യസ്ഥാനത്ത് വെള്ളം കുടയുക കൂടി ചെയ്തു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 186, 186, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهَا: أَنَّهُ لَمَّا كَانَ عَامُ الْفَتْحِ قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى غُسْلِهِ، فَسَتَرَتْ عَلَيْهِ فَاطِمَةُ، ثُمَّ أَخَذَ ثَوْبَهُ فَالْتَحَفَ بِهِ. (خ,ت,ن,جه)', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ): മക്കാവിജയ ദിവസം നബി(സ) കുളിക്കാനൊരുങ്ങിയപ്പോൾ ഫാതിമ(റ) മറയിട്ടു കൊടുത്തു. പിന്നെ തിരുമേനി(സ)തന്റെ വസ്ത്രമെടുത്ത് ചുറ്റി ഉടുത്തു. (ബു,തു,ന,ജ)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ)', null, null, array['خ','ت','ن','جه']::text[], array['ബു','തു','ന','ജ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ قَيْسِ بْنِ سَعْدٍ قَالَ رَضِيَ اللهُ عَنْهُ: أَتَانَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْنَا لَهُ مَاءً فَاغْتَسَلَ، ثُمَّ أَتَيْنَاهُ بِمِلْحَفَةٍ وَرْسِيَّةٍ فَاشْتَمَلَ بِهَا، فَكَأَنِّي أَنْظُرُ إِلَى أَثَرِ الْوَرْسِ عَلَى عُكَنِهِ. (جه)', 'ഖൈസുബ്നു സഅ്ദ്(റ): നബി(സ) ഞങ്ങളുടെയടുത്തു വന്നപ്പോൾ ഞങ്ങൾ നൽകിയ വെള്ളം കൊണ്ട് കുളിച്ചു. പിന്നെ വർസിയ്യ രോമപ്പുതപ്പ് (കുങ്കുമം മുക്കിയ പുതപ്പ്) നബിക്ക് നൽകുകയും അതുപയോഗിച്ച് ശരീരമാകെ പുതക്കുകയും ചെയ്തു. വർസിന്റെ (കുങ്കുമം) അടയാളം നബി(സ)യുടെ പിരടിയിൽ കാണാമായിരുന്നു. (ജ)', 'قَيْسِ بْنِ سَعْدٍ قَالَ', 'ഖൈസുബ്നു സഅ്ദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ خَالَتِهِ مَيْمُونَةَ رَضِيَ اللهُ عَنْهُمْ قَالَتْ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِثَوْبٍ حِينَ اغْتَسَلَ مِنَ الْجَنَابَةِ، فَرَدَّهُ، وَجَعَلَ يَنْفُضُ الْمَاءَ. (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്, അദ്ദേഹത്തിന്റെ മാതൃ സഹോദരി മൈമൂന(റ)യിൽ നിന്ന്: നബി(സ) ജനാബത്ത് കുളിച്ചപ്പോൾ ഞാൻ ഒരു വസ്ത്രവുമായി ചെന്നു. എന്നാൽ നബി(സ) അതു തിരികെ നൽകുകയും (വെള്ളം) തോർത്താൻ തുടങ്ങുകയും ചെയ്തു. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ، عَنْ خَالَتِهِ مَيْمُونَةَ', 'ഇബ്നുഅബ്ബാസ്, അദ്ദേഹത്തിന്റെ മാതൃ സഹോദരി മൈമൂന(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَقَلَبَ جُبَّةَ صُوفٍ كَانَتْ عَلَيْهِ، فَمَسَحَ بِهَا وَجْهَهُ. (جه)', 'സൽമാനുബ്നുൽ ഫാരിസ്(റ): നബി(സ) വുദൂ ചെയ്തു. ശേഷം തിരുമേനിയുടെ രോമം കൊണ്ടുള്ള ജുബ്ബ ഉയർത്തി മുഖം തടവി. (ജ)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുബ്നുൽ ഫാരിസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُقِيمَتِ الصَّلَاةُ، وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَجِيٌّ لِرَجُلٍ،– وَفِي حَدِيثِ عَبْدِ الْوَارِثِ: وَنَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُنَاجِي رَجُلًا – فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى نَامَ الْقَوْمُ. وَفِي حَدِيثِ شُعْبَةَ: فَلَمْ يَزَلْ يُنَاجِيهِ حَتَّى نَامَ أَصْحَابُهُ، ثُمَّ جَاءَ فَصَلَّى بِهِمْ. (م)', 'അനസുബ്നു മാലിക്(റ): നിസ്കാര സമയമായപ്പോൾ നബി(സ) ഒരാളോട് സംസാരിച്ചു കൊണ്ടിരിക്കുകയായിരുന്നു. നബി(സ) നിസ്കാരത്തിനു നിന്നപ്പോഴേക്കും ആളുകൾ ഉറങ്ങിയിരുന്നു. (ശുഅ്ബയുടെ ഹദീസിൽ ഇപ്രകാരമുണ്ട്: സ്വഹാബികൾ ഉറങ്ങുന്നതുവരെ നബി(സ) അദ്ദേഹത്തോട് സംസാരിച്ചു കൊണ്ടിരുന്നു. പിന്നെ വന്ന് അവർക്കിമാമായി നിസ്കരിച്ചു.) (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَائِشَةَ قَالَتْ رَضِيَ اللهُ عَنْهَا: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنَامُ حَتَّى يَنْفُخَ، ثُمَّ يَقُومُ فَيُصَلِّي، وَلَا يَتَوَضَّأُ. (جه)', 'ആഇശ(റ): നബി(സ) കൂർക്കം വലിക്കുന്നതുവരെ ഉറങ്ങുകയും, ശേഷം എഴുന്നേറ്റു നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ഉണർന്നാൽ) വുദൂഅ് ചെയ്യാറില്ല. (ജ)', 'عَائِشَةَ قَالَتْ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 187, 187, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَامَ حَتَّى نَفَخَ، ثُمَّ قَامَ فَصَلَّى. [ز: في إسناده مدلس عنعنه] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) കൂർക്കം വലിക്കുന്നതുവരെ ഉറങ്ങുകയും, ശേഷം എഴുന്നേറ്റു നിസ്കരിക്കുകയും ചെയ്തു. (ഇതിന്റെ പരമ്പരയിൽ ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ نَوْمُهُ ذَلِكَ وَهُوَ جَالِسٌ. يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ ഉറക്കം ഇപ്രകാരമായിരുന്നു. (അദ്ദേഹം ഇരുന്നാണ് ഇപ്രകാരം പറഞ്ഞത്). (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْعَيْنُ وِكَاءُ السَّهِ، فَمَنْ نَامَ فَلْيَتَوَضَّأْ". (د,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ) പറഞ്ഞു: "കണ്ണ് ചന്തിയുടെ കെട്ടാണ്, ഉറങ്ങിയവൻ വുദൂ ചെയ്തുകൊള്ളട്ടെ." (ദ,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ مِنَ اللَّيْلِ، فَدَخَلَ الْخَلَاءَ فَقَضَى حَاجَتَهُ، ثُمَّ غَسَلَ وَجْهَهُ وَكَفَّيْهِ، ثُمَّ نَامَ. (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രാത്രി എഴുന്നേറ്റു. വിസർജ്ജനാവശ്യം നിറവേറ്റി. പിന്നെ രണ്ടു മുൻകൈകളും, മുഖവും കഴുകിയ ശേഷം ഉറങ്ങി. (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا مَسَّ أَحَدُكُمْ ذَكَرَهُ، فَعَلَيْهِ الْوُضُوءُ". [ز: في إسناده مقال] (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ലിംഗം സ്പർശിച്ചാൽ അവൻ വുദൂ ചെയ്തുകൊള്ളട്ടെ." (ഇതിന്റെ പരമ്പരയിൽ മഖാലുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مقال', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ". [ز: في إسناده مقال] (جه)', 'ഉമ്മുഹബീബ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "തന്റെ ഗുഹ്യസ്ഥാനം തൊട്ടവൻ വുദൂ ചെയ്യേണ്ടതാണ്." (ഇതിന്റെ പരമ്പരയിൽ മഖാലുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أُمِّ حَبِيبَةَ', 'ഉമ്മുഹബീബ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مقال', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ". [ز: في إسناده ضعيف] (جه)', 'അബൂഅയ്യൂബ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "തന്റെ ഗുഹ്യസ്ഥാനം സ്പർശിച്ചവൻ വുദൂ ചെയ്തുകൊള്ളട്ടെ." (ജ) [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു]', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['جه']::text[], '{}'::text[], 'ز: في إسناده ضعيف', null, 188, 188, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ طَلْقٍ الْحَنَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ مَسِّ الذَّكَرِ، فَقَالَ: "لَيْسَ فِيهِ وُضُوءٌ، إِنَّمَا هُوَ مِنْكَ". (د,ت,ن,جه)', 'ത്വൽഖുൽ ഹനഫി(റ): ലിംഗ സ്പർശത്തെക്കുറിച്ചു പറഞ്ഞപ്പോൾ നബി(സ) ഇപ്രകാരം പറഞ്ഞതായി ഞാൻ കേട്ടു: "അതിന് വുദൂ ചെയ്യേണ്ടതില്ല, അത് നിന്നിലുള്ള ഒരവയവം മാത്രമാകുന്നു." (ദ,തു,ന,ജ)', 'طَلْقٍ الْحَنَفِيِّ', 'ത്വൽഖുൽ ഹനഫി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ مَسِّ الذَّكَرِ؟ فَقَالَ: "إِنَّمَا هُوَ جِذْيَةٌ مِنْكَ". [ز: في إسناده ضعيف] (جه)', 'അബൂഉമാമ(റ): ലിംഗ സ്പർശത്തെക്കുറിച്ചു പറഞ്ഞപ്പോൾ നബി(സ) ഇപ്രകാരം പറഞ്ഞു: "അത് നിന്നിലുള്ള ഒരു ഭാഗം മാത്രമാകുന്നു." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്വലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَوَضَّئُوا مِمَّا غَيَّرَتِ النَّارُ". فَقَالَ ابْنُ عَبَّاسٍ: أَتَوَضَّأُ مِنَ الْحَمِيمِ؟ فَقَالَ لَهُ: يَا ابْنَ أَخِي، إِذَا سَمِعْتَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا، فَلَا تَضْرِبْ لَهُ الأَمْثَالَ. (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "തീ കൊണ്ട് വേവിക്കപ്പെട്ടതു തിന്നാൽ നിങ്ങൾ വുദൂ ചെയ്യുക. ഇബ്നുഅബ്ബാസ്(റ) ചോദിച്ചു: കരി കൊണ്ട് വേവിക്കപ്പെട്ടതു തിന്നാൽ വുദൂ ചെയ്യേണ്ടതുണ്ടോ? അദ്ദേഹത്തോട് പറയപ്പെട്ടു: സഹോദരപുത്രാ, നബി(സ)യിൽ നിന്നു വല്ലതും കേട്ടാൽ അതിനെ ഉപമിക്കരുത്. (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَوَضَّئُوا مِمَّا مَسَّتِ النَّارُ". (جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "തീ സ്പർശിച്ചതു (വേവിച്ച സാധനം ഭക്ഷിച്ചതു)കാരണത്താൽ നിങ്ങൾ വുദൂ ചെയ്യണം." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ يَضَعُ يَدَيْهِ عَلَى أُذُنَيْهِ وَيَقُولُ: صُمَّتَا، إِنْ لَمْ أَكُنْ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تَوَضَّئُوا مِمَّا مَسَّتِ النَّارُ". [ز: في إسناده مختلف فيه] (جه)', 'അനസുബ്നു മാലിക്(റ): അദ്ദേഹം തന്റെ ഇരുകരങ്ങളും ചെവിയിൽ വെച്ച് ഇപ്രകാരം പറയുമായിരുന്നു: "തീ സ്പർശിച്ചതു (വേവിച്ച സാധനം ഭക്ഷിച്ചതു)കാരണത്താൽ നിങ്ങൾ വുദൂ ചെയ്യുവിൻ!" എന്ന് നബി(സ) പറഞ്ഞതായി ഞാൻ കേട്ടിട്ടില്ലെങ്കിൽ ഇവരണ്ടും (ഇരുചെവികളും) ബധിരമാവട്ടെ. (ഇതിന്റെ പരമ്പരയിലെ ഒരു വ്യക്തിയെക്കുറിച്ച് അഭിപ്രായവ്യത്യാസമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مختلف فيه', null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَكَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَتِفًا، ثُمَّ مَسَحَ يَدَيْهِ بِمَسْحٍ كَانَ تَحْتَهُ، ثُمَّ قَامَ إِلَى الصَّلَاةِ فَصَلَّى. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരിക്കൽ ഒരു കുറക് (മാംസക്കഷ്ണം) തിന്ന് അതിന്റെ അടിയിലുള്ള ഒരു പരുക്കൻ തുണിയുപയോഗിച്ച് കൈകൾ തുടച്ചശേഷം ധൃതിയിൽ നിസ്കാരത്തിലേക്ക് പുറപ്പെട്ടു, നിസ്കരിച്ചു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 189, 189, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: أَكَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ خُبْزًا وَلَحْمًا، وَلَمْ يَتَوَضَّئُوا. (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ)യോടൊപ്പം അബൂബക്കറും(റ), ഉമറും(റ) റൊട്ടിയും മാംസവും ഭക്ഷിച്ചു. എന്നാൽ അവർ വുദൂ ചെയ്തില്ല. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ: أَشْهَدُ عَلَى أَبِي أَنَّهُ شَهِدَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ أَكَلَ طَعَامًا مِمَّا غَيَّرَتِ النَّارُ، ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ. وَقَالَ عَلِيُّ بْنُ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: وَأَنَا أَشْهَدُ عَلَى أَبِي بِمِثْلِ ذَلِكَ. (خ,ت,جه)', 'ജഅ്ഫറുബ്നു അംറുബ്നു ഉമയ്യ(റ): നബി(സ) തീ കൊണ്ട് വേവിച്ച ഭക്ഷണം കഴിച്ചതായി എന്റെ പിതാവ് കണ്ടതായി ഞാൻ പറയുന്നു. ശേഷം വുദൂ ചെയ്യാതെ നിസ്കരിക്കുകയും ചെയ്തു. അലിയ്യുബ്നു അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ) പറയുന്നു: അപ്രകാരം എന്റെ പിതാവിനെയും ഞാൻ സാക്ഷ്യപ്പെടുത്തുന്നു. (ബു,തു,ജ)', 'جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ', 'ജഅ്ഫറുബ്നു അംറുബ്നു ഉമയ്യ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَتِفِ شَاةٍ فَأَكَلَ مِنْهُ، وَصَلَّى وَلَمْ يَمَسَّ مَاءً. (ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) ഞങ്ങളുടെയടുത്ത് ആടിൻ കുറക് കൊണ്ടുവന്നപ്പോൾ അത് ഭക്ഷിക്കുകയും, വെള്ളം തൊടാതെ (വുദൂ ചെയ്യാതെ) നിസ്കരിക്കുകയും ചെയ്തു. (ന,ജ)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ، عَنْ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ سُوَيْدِ بْنِ النُّعْمَانِ الأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُمْ خَرَجُوا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى خَيْبَرَ، حَتَّى إِذَا كَانُوا بِالصَّهْبَاءِ صَلَّى الْعَصْرَ، ثُمَّ دَعَا بِأَطْعِمَةٍ، فَلَمْ يُؤْتَ إِلَّا بِسَوِيقٍ، فَأَكَلُوا وَشَرِبُوا، ثُمَّ دَعَا بِمَاءٍ فَمَضْمَضَ فَاهُ، ثُمَّ قَامَ فَصَلَّى بِنَا الْمَغْرِبَ. (خ,ن,جه)', 'സുവൈദുബ്നു നുഅ്മാനിൽ അൻസ്വാരി(റ): അവർ (സഹാബികൾ) നബി(സ)യോടൊപ്പം ഖൈബറിലേക്കു പുറപ്പെട്ടു. സ്വഹ്ബാഅ് എന്ന സ്ഥലത്തെത്തിയപ്പോൾ അസ്വർ നിസ്കരിച്ചു. ശേഷം ഭക്ഷണമാവശ്യപ്പെട്ടപ്പോൾ ഉണക്ക റൊട്ടി മാത്രമാണ് കൊണ്ടുവരപ്പെട്ടത്. അതവർ നന്നായി ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്തശേഷം വെള്ളമാവശ്യപ്പെടുകയും, വായ കൊപ്ലിക്കുകയും ചെയ്ത് എഴുന്നേറ്റ് ഞങ്ങളോടൊപ്പം മഗ്രിബ് നിസ്കരിച്ചു. (ബു,ന,ജ)', 'سُوَيْدِ بْنِ النُّعْمَانِ الأَنْصَارِيِّ', 'സുവൈദുബ്നു നുഅ്മാനിൽ അൻസ്വാരി(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَكَلَ كَتِفَ شَاةٍ، فَمَضْمَضَ وَغَسَلَ يَدَيْهِ وَصَلَّى. (جه)', 'അബൂഹുറൈറ(റ) നബി(സ) ആടിന്റെ കുറക് ഭക്ഷിക്കുകയും (വായ) കൊപ്ലിക്കുകയും കൈ കഴുകുകയും ചെയ്തശേഷമാണു നിസ്കരിച്ചത്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَتَوَضَّأَ مِنْ لُحُومِ الإِبِلِ وَلَا نَتَوَضَّأَ مِنْ لُحُومِ الْغَنَمِ. (م)', 'ജാബിറുബ്നു സമുറ(റ): ഒട്ടക മാംസം തിന്നാൽ വുദൂ ചെയ്യണമെന്നും ആട്ടിൻ മാംസം തിന്നാൽ വുദൂ ചെയ്യേണ്ടതില്ലെന്നും നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 190, 190, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَتَوَضَّئُوا مِنْ أَلْبَانِ الْغَنَمِ، وَتَوَضَّئُوا مِنْ أَلْبَانِ الإِبِلِ". (جه)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ആട്ടിൻപാൽ കുടിച്ചാൽ വുദൂ ചെയ്യേണ്ടതില്ല, ഒട്ടകപ്പാൽ കുടിച്ചാൽ വുദൂ ചെയ്യുക. (ജ)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تَوَضَّئُوا مِنْ لُحُومِ الإِبِلِ، وَلَا تَتَوَضَّئُوا مِنْ لُحُومِ الْغَنَمِ، وَتَوَضَّئُوا مِنْ أَلْبَانِ الإِبِلِ، وَلَا تَوَضَّئُوا مِنْ أَلْبَانِ الْغَنَمِ، وَصَلُّوا فِي مُرَاحِ الْغَنَمِ، وَلَا تُصَلُّوا فِي مَعَاطِنِ الإِبِلِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങൾ ഒട്ടക മാംസം തിന്നാൽ വുദൂ ചെയ്യുക, ആട്ടിൻ മാംസം തിന്നാൽ വുദൂ ചെയ്യേണ്ടതില്ല. ഒട്ടകപ്പാൽ കുടിച്ചാൽ വുദൂ ചെയ്യുക, ആട്ടിൻപാൽ കുടിച്ചാൽ വുദൂ ചെയ്യേണ്ടതില്ല. ആടിന്റെ ആലയിൽ വെച്ച് നിസ്കരിക്കാം, എന്നാൽ ഒട്ടകത്തൊഴുത്തിൽ വെച്ച് നിങ്ങൾ നിസ്കരിക്കരുത്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَضْمِضُوا مِنَ اللَّبَنِ، فَإِنَّ لَهُ دَسَمًا". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പാൽ കുടിച്ചാൽ കൊപ്ലിക്കുക. കാരണം, അതിൽ നെയ്യുണ്ട്." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أُمِّ سَلَمَةَ – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَرِبْتُمُ اللَّبَنَ فَمَضْمِضُوا، فَإِنَّ لَهُ دَسَمًا". (جه)', 'പ്രവാചകപത്നി ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പാൽ കുടിച്ചാൽ വെള്ളം കൊള്ളുക. കാരണം, അതിൽ നെയ്യുണ്ട്." (ജ)', 'أُمِّ سَلَمَةَ – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'പ്രവാചകപത്നി ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَضْمِضُوا مِنَ اللَّبَنِ، فَإِنَّ لَهُ دَسَمًا". (جه)', 'സഹ്ലുബ്നു സഅ്ദിനിസ്സാഇദി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പാൽ കുടിച്ചാൽ വെള്ളം കൊള്ളുക. കാരണം, അതിൽ നെയ്യുണ്ട്. (ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിനിസ്സാഇദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَوَضَّأُ، ثُمَّ يُقَبِّلُ وَيُصَلِّي وَلَا يَتَوَضَّأُ وَرُبَّمَا فَعَلَهُ بِي. (جه)', 'ആഇശ(റ): നബി(സ) വുദൂ ചെയ്തശേഷം ചുംബിക്കുകയും, വീണ്ടും വുദൂ ചെയ്യാതെ നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. നബി(സ) അധികവും എന്നോടായിരുന്നു ഇപ്രകാരം ചെയ്തിരുന്നത്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 191, 191, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنِ الْمِقْدَادِ بْنِ الأَسْوَدِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يَدْنُو مِنِ امْرَأَتِهِ فَلَا يُنْزِلُ؟ قَالَ: "إِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَنْضَحْ فَرْجَهُ – يَعْنِي لِيَغْسِلَهُ– وَيَتَوَضَّأْ". (د,ن,جه)', 'മിഖ്ദാദുബ്നു അസ്വദ്(റ): തന്റെ ഭാര്യയോടൊപ്പം ശയിച്ചിട്ടും സ്ഖലനം സംഭവിക്കാത്ത ഒരാളെപ്പറ്റി അദ്ദേഹം നബി(സ)യോട് പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും അപ്രകാരം സംഭവിച്ചാൽ അവൻ അവന്റെ ഗുഹ്യസ്ഥാനത്ത് വെള്ളം കുടയുകയും, പിന്നെ വുദൂ ചെയ്യുകയും ചെയ്യണം." (ദ,ന,ജ)', 'الْمِقْدَادِ بْنِ الأَسْوَدِ', 'മിഖ്ദാദുബ്നു അസ്വദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 192, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى أُبَيَّ بْنَ كَعْبٍ وَمَعَهُ عُمَرُ رضي الله عنه، فَخَرَجَ عَلَيْهِمَا فَقَالَ: إِنِّي وَجَدْتُ مَذْيًا، فَغَسَلْتُ ذَكَرِي وَتَوَضَّأْتُ؟ فَقَالَ عُمَرُ: أَوَ يُجْزِئُ ذَلِكَ؟ قَالَ: نَعَمْ، قَالَ: أَسَمِعْتَهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമറി(റ)നോടൊപ്പം നിൽക്കുന്ന ഉബയ്യുബ്നു കഅ്ബി(റ)ന്റെ അടുത്തു ചെന്ന് അദ്ദേഹം പറഞ്ഞു: ഞാൻ മദ്‌യ് കണ്ടപ്പോൾ ഗുഹ്യസ്ഥാനം കഴുകി വുദൂ ചെയ്തു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അതു മതിയോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ. ഉമർ(റ) ചോദിച്ചു: നിങ്ങളിക്കാര്യത്തെപ്പറ്റി നബി(സ)യിൽ നിന്നു വല്ലതും കേട്ടിട്ടുണ്ടോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അതെ. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 192, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رُبَّمَا فَرَكْتُهُ مِنْ ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِي. (م,د,ن,جه)', 'ആഇശ(റ): നബി(സ)യുടെ വസ്ത്രത്തിൽ ഞാൻ പലപ്പോഴും എന്റെ കൈ കൊണ്ട് അതിനെ (സ്വപ്നസ്ഖലനാവശിഷ്ടം) ചുരണ്ടിക്കളയാറുണ്ട്. (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 192, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ رَأَيْتُنِي أَجِدُهُ فِي ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَحُتُّهُ عَنْهُ. (م,ن,جه)', 'ആഇശ(റ): പലപ്പോഴും നബി(സ)യുടെ വസ്ത്രത്തിൽ ഞാനത് (മനിയ്യ്) കാണുകയും അതിനെ ചുരണ്ടിക്കളയുകയും ചെയ്യാറുണ്ട്. (മു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 192, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَجَدَ أَحَدُكُمْ فِي بَطْنِهِ شَيْئًا، فَأَشْكَلَ عَلَيْهِ أَخَرَجَ مِنْهُ شَيْءٌ أَمْ لَا؟ فَلَا يَخْرُجَنَّ مِنَ الْمَسْجِدِ حَتَّى يَسْمَعَ صَوْتًا، أَوْ يَجِدَ رِيحًا". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾക്ക് വയറ്റിൽ വല്ലതും അനുഭവപ്പെടുകയും, അതിൽ നിന്ന് വല്ലതും പുറപ്പെട്ടോ ഇല്ലേ എന്ന് സംശയിക്കുകയും ചെയ്താൽ ശബ്ദം കേൾക്കുന്നതുവരെ, അല്ലെങ്കിൽ കാറ്റ് വരുന്നതുവരെ അവൻ പള്ളിയിൽ നിന്ന് പുറത്തു പോവരുത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 192, 192, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
